/// The meeting a move between meetings left (its link, title and breakout
/// state), to go back to when the move fails.
#[derive(Clone, Default)]
struct MoveUndo {
    url: QString,
    title: QString,
    breakout_json: QString,
    breakout_room_json: QString,
}

/// The call this app is ringing for or in. Lives on the engine side so the
/// media keeps running independently of the Qt thread.
#[derive(Default)]
struct CallSlot {
    ringing: Option<IncomingCall>,
    active: Option<ActiveCall>,
    outgoing: Option<OutgoingCall>,
    /// The meeting we're moving out of (to a breakout room or back): its
    /// media is off, and it is left once the next meeting answers.
    moved_from: Option<OutgoingCall>,
    /// The ids of the meetings we moved out of: their ends are theirs.
    left_calls: Vec<String>,
    /// The main meeting on hold while its organizer is in a breakout room
    /// (Teams' Join on a room's menu), with its link and title.
    held_main: Option<(OutgoingCall, QString, QString)>,
    /// Going back from a breakout room into a main meeting that holds us in
    /// its lobby: Teams stays in the room (its window and call) until the
    /// main meeting lets us in, then leaves it (watched on winpc
    /// 2026-11-18: the main meeting's call InLobby, the room's Connected).
    /// The main meeting's call, its link and title.
    lobby_return: Option<(OutgoingCall, QString, QString)>,
    /// The callback tags of the calls we moved out of: their events
    /// (their conversation ending as we leave) are theirs.
    left_tags: Vec<String>,
    /// Withdraws the call being placed (still ringing the callee).
    cancel_placing: Option<tokio::sync::oneshot::Sender<()>>,
    /// The second call of a consult (Teams' Consult then transfer, Merge
    /// Calls) while the first waits on hold, its callback tag, where the
    /// consult stands, and what withdraws it while it rings.
    consult: Option<OutgoingCall>,
    consult_tag: Option<String>,
    consult_state: teams_cli::calling::consult::Consult,
    /// A transfer or park replaced the answered (untagged) call: its end
    /// is not the end of the call we're now in.
    superseded_untagged: bool,
    /// When we answered a group chat's call by joining its conversation:
    /// the invitation itself stays unanswered and the service ends it
    /// about a minute later (untagged: 408 "Call timed out without any
    /// signaling after attach from callee endpoints"). That end isn't ours.
    group_invite_at: Option<std::time::Instant>,
    /// A consult transfer replaced the answered call with this person
    /// (the transferor): its ends, which name them, aren't ours.
    replaced_peer: Option<String>,
    /// Each remote person's merge leg from roster events, by lowercase MRI,
    /// whatever call was in the slot then: an answered call's first roster
    /// arrives with its acceptance, before the call is stored, and the
    /// held call's person is in no other call, so a merge finds them here.
    roster_legs: std::collections::HashMap<String, serde_json::Value>,
    cancel_consult: Option<tokio::sync::oneshot::Sender<()>>,
    /// The screen picked to share, waiting for Teams to take our re-offer.
    share_pending: Option<(
        teams_cli::calling::screencast::ScreenCapture,
        std::sync::mpsc::Receiver<teams_cli::calling::camera::YuvFrame>,
    )>,
    /// The meeting the pre-join window shows, joined hidden (Teams'
    /// preheat) until Join now or Cancel.
    preheat: Option<Preheat>,
    /// The main meeting's conversation, kept without a call while we're
    /// in one of its breakout rooms (Teams': its updates keep coming, and
    /// going back posts the call straight to it).
    kept_main: Option<outgoing::KeptConversation>,
    /// A participant's main meeting held under a room that couldn't be
    /// joined: its breakout state (assignments, room), restored on Resume.
    held_breakout: Option<(String, String)>,
}

/// Teams' preheated pre-join call (Teams on the web, 2026-11-16): joined
/// hidden as the pre-join window opens, so the window knows whether the
/// meeting offers Phone audio; Join now makes it visible, Cancel leaves
/// it, and after a minute (ECS `preheatedCallTimeoutInMs`) Teams leaves
/// it by itself (Join now then joins afresh).
struct Preheat {
    /// The meeting's join link.
    url: String,
    /// The call's callback tag: its events are the pre-join's, not a
    /// call's.
    tag: String,
    /// The preheated call, once the meeting answered.
    call: Option<OutgoingCall>,
    /// Withdraws the call while it is still being placed.
    cancel: Option<tokio::sync::oneshot::Sender<()>>,
    /// Ends its watcher (joined or cancelled).
    stop: std::sync::Arc<tokio::sync::Notify>,
    /// The breakout rooms its updates assign us (call_breakout_json): a
    /// late joiner's room comes while the call is preheated, and Join now
    /// starts from it.
    breakout: Option<String>,
    /// Join now is waiting for it to be placed: closing the pre-join
    /// window mustn't withdraw it.
    joining: bool,
}

/// How long Teams keeps a preheated call (ECS `preheatedCallTimeoutInMs`).
const PREHEAT_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(60);

/// The connected call, answered or placed: what changing our media
/// (camera, screen) needs from it.
enum MediaCall<'a> {
    Answered(&'a mut ActiveCall),
    Placed(&'a mut OutgoingCall),
}

macro_rules! either {
    ($self:expr, $c:ident => $e:expr) => {
        match $self {
            MediaCall::Answered($c) => $e,
            MediaCall::Placed($c) => $e,
        }
    };
}

impl MediaCall<'_> {
    fn of(slot: &mut CallSlot) -> Option<MediaCall<'_>> {
        match (slot.active.as_mut(), slot.outgoing.as_mut()) {
            (Some(c), _) => Some(MediaCall::Answered(c)),
            (None, Some(c)) => Some(MediaCall::Placed(c)),
            _ => None,
        }
    }

    async fn offer_media(&mut self, change: Reoffer) -> anyhow::Result<()> {
        match self {
            MediaCall::Answered(c) => c.offer_media(&CallAuth::load().await?, change).await,
            MediaCall::Placed(c) => c.offer_media(change).await,
        }
    }

    async fn acknowledge_answer(&self, link: &str) -> anyhow::Result<()> {
        match self {
            MediaCall::Answered(c) => c.acknowledge_answer(&CallAuth::load().await?, link).await,
            MediaCall::Placed(c) => c.acknowledge_answer(link).await,
        }
    }

    fn can_reoffer(&self) -> bool {
        either!(self, c => c.can_reoffer())
    }

    /// A meeting's (or group call's) camera and screen go on and off by
    /// media descriptions, as Teams does, not re-offers.
    fn describes_media(&self) -> bool {
        matches!(self, MediaCall::Placed(c) if c.describes_media())
    }

    fn can_share(&self) -> bool {
        either!(self, c => c.can_share())
    }

    fn reoffer_pending(&self) -> bool {
        either!(self, c => c.reoffer_pending())
    }

    fn take_reoffer_answer(&mut self, answer: &str) -> anyhow::Result<(Reoffer, bool)> {
        either!(self, c => c.take_reoffer_answer(answer))
    }

    fn cancel_reoffer(&self) {
        either!(self, c => c.cancel_reoffer())
    }

    fn set_camera(&mut self, on: bool) -> anyhow::Result<()> {
        either!(self, c => c.set_camera(on, camera_device()))
    }

    fn start_share(
        &mut self,
        capture: teams_cli::calling::screencast::ScreenCapture,
        frames: std::sync::mpsc::Receiver<teams_cli::calling::camera::YuvFrame>,
    ) -> anyhow::Result<()> {
        either!(self, c => c.start_share(capture, frames))
    }

    fn stop_share(&mut self) {
        either!(self, c => c.stop_share())
    }

    fn is_sharing(&self) -> bool {
        either!(self, c => c.is_sharing())
    }

    fn share_ended(&self) -> bool {
        either!(self, c => c.share_ended())
    }
}

/// Tell a meeting what our camera and sharing lines now do, as Teams
/// does when either changes.
async fn describe_media(call: Option<&OutgoingCall>) -> anyhow::Result<()> {
    match call {
        Some(o) => o.describe_media(o.camera_on(), o.is_sharing()).await,
        None => Ok(()),
    }
}

/// Ask the desktop what to share (its picker), then offer it to the call.
/// Sending starts when Teams answers ([`reoffer_reply`]); in a meeting it
/// starts at once and the meeting is told (returns true).
async fn offer_screen(kind: teams_cli::calling::screencast::Source) -> anyhow::Result<bool> {
    // Only open the desktop's picker when the call can take a screen.
    {
        let mut slot = call_slot().lock().await;
        let call = MediaCall::of(&mut slot).context("The call has ended")?;
        anyhow::ensure!(call.can_share(), "This call can't take a shared screen");
    }
    let (capture, frames) = teams_cli::calling::screencast::ScreenCapture::start_kind(kind).await?;
    offer_capture(capture, frames).await
}

/// Teams' Content from camera: share this camera as the screen is.
async fn offer_camera_content(camera: teams_cli::calling::content_camera::ContentCamera) -> anyhow::Result<bool> {
    {
        let mut slot = call_slot().lock().await;
        let call = MediaCall::of(&mut slot).context("The call has ended")?;
        anyhow::ensure!(call.can_share(), "This call can't take shared content");
    }
    let (capture, frames) = teams_cli::calling::screencast::ScreenCapture::from_content_camera(&camera);
    offer_capture(capture, frames).await
}

/// The content camera of Content from camera's setup dialog.
fn content_camera() -> &'static std::sync::Mutex<Option<teams_cli::calling::content_camera::ContentCamera>> {
    static C: std::sync::Mutex<Option<teams_cli::calling::content_camera::ContentCamera>> = std::sync::Mutex::new(None);
    &C
}

/// Offer what's captured to the call (see [`offer_screen`]).
async fn offer_capture(
    capture: teams_cli::calling::screencast::ScreenCapture,
    frames: std::sync::mpsc::Receiver<teams_cli::calling::camera::YuvFrame>,
) -> anyhow::Result<bool> {
    let mut guard = call_slot().lock().await;
    let slot = &mut *guard;
    let mut call = MediaCall::of(slot).context("The call has ended")?;
    if call.describes_media() {
        call.start_share(capture, frames)?;
        if let Err(e) = describe_media(slot.outgoing.as_ref()).await {
            if let Some(mut call) = MediaCall::of(slot) {
                call.stop_share();
            }
            return Err(e);
        }
        return Ok(true);
    }
    call.offer_media(Reoffer::Share(true)).await?;
    slot.share_pending = Some((capture, frames));
    Ok(false)
}

/// Re-offer the meeting's audio when spatial audio wants it the other way
/// (Teams' audio codec manager raising negotiationNeeded): x-much2 asked
/// for or given up; the answer comes back through [`reoffer_reply`].
async fn sync_unmixed_audio() {
    let mut guard = call_slot().lock().await;
    let Some(call) = guard.outgoing.as_mut() else { return };
    let Some(change) = call.unmixed_change() else { return };
    if call.reoffer_pending() {
        tracing::info!("spatial audio: a re-offer is pending; renegotiating later");
        return;
    }
    tracing::info!(?change, "spatial audio: renegotiating the meeting's audio");
    if let Err(e) = call.offer_media(change).await {
        tracing::warn!("spatial audio re-offer: {}", short_error(&e));
    }
}

/// Stop sending our screen and tell the call.
async fn stop_screen() -> anyhow::Result<()> {
    let mut guard = call_slot().lock().await;
    let slot = &mut *guard;
    slot.share_pending = None;
    let mut call = MediaCall::of(slot).context("The call has ended")?;
    call.stop_share();
    if call.describes_media() {
        return describe_media(slot.outgoing.as_ref()).await;
    }
    call.offer_media(Reoffer::Share(false)).await
}

/// Teams' reply to a re-offer of ours (camera or screen). Returns false
/// when it isn't one (some other mediaAnswer), so the event is handled as
/// before.
async fn reoffer_reply(
    qt: &cxx_qt::CxxQtThread<qobject::Backend>,
    reply: anyhow::Result<teams_cli::calling::incoming::ReofferAnswer>,
) -> bool {
    let mut guard = call_slot().lock().await;
    let slot = &mut *guard;
    let pending = slot.share_pending.take();
    let Some(mut call) = MediaCall::of(slot).filter(|c| c.reoffer_pending()) else {
        slot.share_pending = pending;
        return false;
    };
    let outcome = match reply {
        Ok(answer) => {
            if let Some(link) = &answer.ack
                && let Err(e) = call.acknowledge_answer(link).await
            {
                tracing::warn!("re-offer: {}", short_error(&e));
            }
            call.take_reoffer_answer(&answer.sdp)
        }
        Err(e) => {
            call.cancel_reoffer();
            Err(e)
        }
    };
    // What the UI shows afterwards: (camera, sharing), when they change.
    let result: anyhow::Result<(Option<bool>, Option<bool>)> = match (outcome, pending) {
        (Ok((Reoffer::Share(true), true)), Some((capture, frames))) => call
            .start_share(capture, frames)
            .map(|()| (None, Some(true))),
        (Ok((Reoffer::Share(true), _)), _) => {
            Err(anyhow::anyhow!("The call didn't take your screen"))
        }
        (Ok((Reoffer::Share(false), _)), _) => Ok((None, Some(false))),
        (Ok((Reoffer::Camera(true), true)), _) => {
            call.set_camera(true).map(|()| (Some(true), None))
        }
        (Ok((Reoffer::Camera(true), false)), _) => {
            Err(anyhow::anyhow!("The call didn't take your camera"))
        }
        (Ok((Reoffer::Camera(false), _)), _) => Ok((Some(false), None)),
        (Ok((Reoffer::Unmixed(on), taken)), _) => {
            tracing::info!(asked = on, taken, "spatial audio: meeting audio renegotiated");
            Ok((None, None))
        }
        (Err(e), _) => Err(e),
    };
    // A meeting is told what our camera and sharing lines now do, as Teams
    // does, so its roster shows them and others can ask for them.
    drop(guard);
    match result {
        Ok((camera, sharing)) => {
            tracing::info!(?camera, ?sharing, "media changed");
            let _ = qt.queue(move |mut this| {
                if let Some(c) = camera {
                    this.as_mut().set_call_camera_on(c);
                }
                if let Some(s) = sharing {
                    this.as_mut().set_call_sharing(s);
                }
            });
            if sharing == Some(true) {
                spawn_share_watch(qt.clone());
            }
        }
        Err(e) => {
            tracing::warn!("re-offer: {}", short_error(&e));
            let _ = qt.queue(move |mut this| {
                this.as_mut().set_call_sharing(false);
                this.as_mut()
                    .set_status_text(QString::from(short_error(&e).as_str()));
            });
        }
    }
    true
}

/// While we share: when the shared window goes away (or sharing is
/// stopped from the desktop), stop and tell the call, as Teams does.
fn spawn_share_watch(qt: cxx_qt::CxxQtThread<qobject::Backend>) {
    runtime().spawn(async move {
        loop {
            tokio::time::sleep(std::time::Duration::from_secs(1)).await;
            let mut slot = call_slot().lock().await;
            let Some(call) = MediaCall::of(&mut slot) else {
                return;
            };
            if !call.is_sharing() {
                return;
            }
            if call.share_ended() {
                drop(slot);
                if let Err(e) = stop_screen().await {
                    tracing::warn!("share: {}", short_error(&e));
                }
                let _ = qt.queue(|mut this| this.as_mut().set_call_sharing(false));
                return;
            }
        }
    });
}

/// The chat call we're watching without joining (its live roster).
fn watched_call() -> &'static tokio::sync::Mutex<Option<teams_cli::calling::live_roster::LiveRoster>>
{
    static W: OnceLock<tokio::sync::Mutex<Option<teams_cli::calling::live_roster::LiveRoster>>> =
        OnceLock::new();
    W.get_or_init(Default::default)
}

/// The live meetings' calls the Live meetings dialog watches, by thread.
fn watched_meetings() -> &'static tokio::sync::Mutex<HashMap<String, teams_cli::calling::live_roster::LiveRoster>> {
    static W: OnceLock<tokio::sync::Mutex<HashMap<String, teams_cli::calling::live_roster::LiveRoster>>> = OnceLock::new();
    W.get_or_init(Default::default)
}

/// {threadId: [{id, name}]} for the Live meetings dialog's avatar rows.
fn meeting_rosters_json(map: &HashMap<String, teams_cli::calling::live_roster::LiveRoster>) -> String {
    let mut out = serde_json::Map::new();
    for (thread, sub) in map {
        out.insert(thread.clone(), serde_json::Value::Array(sub.others().map(|p| serde_json::json!({"id": p.id, "name": p.name})).collect()));
    }
    serde_json::Value::Object(out).to_string()
}

/// The watched call's roster for the header: [{id, name}] of who's in it.
fn live_roster_json(w: &teams_cli::calling::live_roster::LiveRoster) -> String {
    let people: Vec<serde_json::Value> = w
        .others()
        .map(|p| serde_json::json!({"id": p.id, "name": p.name}))
        .collect();
    serde_json::to_string(&people).unwrap_or_else(|_| "[]".into())
}

/// Run a breakout rooms action on the meeting `link` names and read the
/// rooms and settings back (the state call_breakout_rooms_json shows).
async fn breakout_run(action: &str, args: &serde_json::Value, link: &outgoing::MeetingLink) -> anyhow::Result<serde_json::Value> {
    use api::breakout_rooms as br;
    let main = br::Coords::new(
        link.tenant_id.as_deref().unwrap_or_default(),
        link.organizer_id.as_deref().unwrap_or_default(),
        &link.thread_id,
        &link.message_id,
    )?;
    let me = call_slot().lock().await.outgoing.as_ref().map(|c| c.participant_id().to_string()).unwrap_or_default();
    breakout_run_at(action, args, &main, &br::new_version(&me)).await
}

/// A breakout rooms action on the meeting at `main`: `version` is the
/// change's `newVersion` (empty before the meeting: Teams' Breakout Rooms
/// tab sends none, services-breakout-rooms `g`).
async fn breakout_run_at(
    action: &str,
    args: &serde_json::Value,
    main: &api::breakout_rooms::Coords,
    version: &str,
) -> anyhow::Result<serde_json::Value> {
    use api::breakout_rooms as br;
    let client = TeamsClient::new().await?;
    let main = main.clone();
    let version = version.to_string();
    let total = args["total"].as_u64().unwrap_or(0) as usize;
    let str_of = |v: &serde_json::Value| v.as_str().unwrap_or_default().to_string();
    let rooms_now = || async { br::list(&client, &main).await };
    let pick = |rooms: &[br::Room], threads: &serde_json::Value| -> Vec<br::Coords> {
        let wanted: Vec<String> = threads.as_array().map(|a| a.iter().map(str_of).collect()).unwrap_or_default();
        rooms.iter().filter(|r| wanted.is_empty() || wanted.contains(&r.coords.thread)).map(|r| r.coords.clone()).collect()
    };
    let find = |rooms: &[br::Room], thread: &str| rooms.iter().find(|r| r.coords.thread == thread).cloned();
    let mut csv_warnings: Vec<String> = Vec::new();
    match action {
        "refresh" => {}
        "create" => {
            let rooms: Vec<br::NewRoom> = args["rooms"]
                .as_array()
                .into_iter()
                .flatten()
                .map(|r| br::NewRoom {
                    name: str_of(&r["name"]),
                    participants: r["participants"].as_array().cloned().unwrap_or_default(),
                })
                .collect();
            if rooms.is_empty() {
                anyhow::bail!("No rooms to create");
            }
            let settings = args.get("settings").map(br::Settings::from_args);
            br::create(&client, &main, &rooms, settings.as_ref(), &version).await?;
        }
        "assign" => {
            let current = rooms_now().await?;
            let mut rooms = Vec::new();
            for r in args["rooms"].as_array().into_iter().flatten() {
                let mut room = find(&current, &str_of(&r["thread"])).context("No such room")?;
                if let Some(n) = r["name"].as_str() {
                    room.name = n.to_string();
                }
                room.participants = r["participants"].as_array().cloned().unwrap_or_default();
                rooms.push(room);
            }
            br::assign(&client, &main, &rooms, total, &version).await?;
        }
        "open" | "close" => {
            let current = rooms_now().await?;
            let rooms = pick(&current, &args["threads"]);
            if rooms.is_empty() {
                anyhow::bail!("No rooms");
            }
            if action == "open" {
                br::open(&client, &main, &rooms, total, &version).await?;
            } else {
                br::close(&client, &main, &rooms, total, &version).await?;
            }
        }
        "settings" => {
            br::set_settings(&client, &main, &br::Settings::from_args(args), &version).await?;
        }
        "add" => br::add_room(&client, &main, &str_of(&args["name"]), &[], &version).await?,
        "rename" => {
            let mut room = find(&rooms_now().await?, &str_of(&args["thread"])).context("No such room")?;
            room.name = str_of(&args["name"]);
            br::update_room(&client, &room, &version).await?;
        }
        "delete" => {
            let room = find(&rooms_now().await?, &str_of(&args["thread"])).context("No such room")?;
            br::delete_room(&client, &room.coords, &version).await?;
        }
        "delete_all" => br::delete_all(&client, &main, &rooms_now().await?, &version).await?,
        // Teams' Download CSV template: saved to Downloads.
        "csv_template" => {
            let dir = download_dir().context("No Downloads folder")?;
            let path = api::files::save_unique(&dir, br::CSV_TEMPLATE_NAME, br::CSV_TEMPLATE.as_bytes())?;
            tracing::info!(path = %path.display(), "breakout CSV template saved");
        }
        // Teams' Import from CSV: the rooms and their people from the file,
        // matched by email to the meeting's invitees; rooms already made
        // are replaced.
        "import_csv" => {
            let path = std::path::PathBuf::from(str_of(&args["path"]));
            if path.extension().and_then(|e| e.to_str()).map(|e| e.to_ascii_lowercase()) != Some("csv".into()) {
                anyhow::bail!("We couldn't import this file. The file type, size, or content isn't supported. Please update the file and try again.");
            }
            let text = std::fs::read_to_string(&path).context("We couldn't import this file. The file type, size, or content isn't supported. Please update the file and try again.")?;
            let import = br::parse_csv(&text)?;
            let invitees = api::meeting_options::get(&client, &main.tenant, &main.organizer, &main.thread, &main.message).await?.invitees;
            let mut warnings: Vec<&str> = import.warnings.clone();
            let mut rooms = Vec::new();
            for (name, emails) in &import.rooms {
                let mut people = Vec::new();
                for email in emails {
                    let found = invitees.iter().find(|i| {
                        i["upn"].as_str().or(i["email"].as_str()).is_some_and(|u| u.eq_ignore_ascii_case(email))
                    });
                    match found {
                        Some(i) if i["mri"].is_string() && i["objectId"].is_string() => people.push(json!({
                            "upn": email, "mri": i["mri"], "objectId": i["objectId"], "role": "admin",
                            "tenantId": i.get("tenantId").cloned().unwrap_or(json!(main.tenant)),
                        })),
                        _ => {
                            if !warnings.contains(&"UNMATCHED_PARTICIPANTS") {
                                warnings.push("UNMATCHED_PARTICIPANTS");
                            }
                        }
                    }
                }
                rooms.push(br::NewRoom { name: name.clone(), participants: people });
            }
            let existing = rooms_now().await?;
            if !existing.is_empty() {
                br::delete_all(&client, &main, &existing, &(if version.is_empty() { String::new() } else { br::new_version(version.split('_').next().unwrap_or_default()) })).await?;
            }
            br::create(&client, &main, &rooms, None, &version).await?;
            tracing::info!(rooms = rooms.len(), ?warnings, "breakout rooms imported");
            csv_warnings = warnings.iter().map(|w| w.to_string()).collect();
        }
        "announce" => {
            let threads: Vec<String> = rooms_now().await?.into_iter().map(|r| r.coords.thread).collect();
            br::announce(&client, &main, &threads, &str_of(&args["message"])).await?;
        }
        other => anyhow::bail!("Unknown breakout action {other}"),
    }
    let rooms = rooms_now().await?;
    let settings = br::settings(&client, &main).await.unwrap_or_default();
    Ok(json!({
        "rooms": rooms.iter().map(|r| json!({
            "name": r.name,
            "thread": r.coords.thread,
            "join_url": r.join_url,
            "open": r.open,
            "participants": r.participants,
        })).collect::<Vec<_>>(),
        "settings": settings,
        "loaded": true,
        "warnings": csv_warnings,
    }))
}

/// What the call window shows of a meeting once it's joined (or resumed).
struct JoinedView {
    invite: String,
    capability: teams_cli::calling::meeting_options::MeetingCapability,
    processing: teams_cli::calling::roster::Processing,
    ai_indicator: bool,
    has_audio: bool,
    can_dtmf: bool,
    // Camera and Share as the joined media allows (in the lobby Share
    // waits for the admission's links).
    can_video: bool,
    can_share: bool,
    started: bool,
    timers: teams_cli::calling::meeting_timer::Timers,
    /// The meeting's phone audio (call_phone_json, no call me yet).
    phone: String,
    /// The meeting as a town hall or webinar (call_event_json).
    event: String,
    /// Watching the meeting's stream (a town hall's attendee): the stream
    /// on offer and whether we wait in its lobby.
    stream: Option<(Option<teams_cli::calling::live_stream::StreamChoice>, bool)>,
    /// The breakout rooms the join already assigns us (call_breakout_json;
    /// empty when none).
    breakout: String,
}

/// call_phone_json for a call: Teams' PSTN state and dial-in details, and
/// where "Call me" stands.
fn phone_json(call: &OutgoingCall, state: &str, number: &str, error: &str) -> String {
    let p = call.phone_audio();
    serde_json::json!({
        "available": p.available,
        "dialIn": p.dial_in,
        "dialOut": p.dial_out,
        "dial": call.dial_in().map(|d| d.to_json()),
        "state": state,
        "number": number,
        "error": error,
    })
    .to_string()
}

/// The number "Call me" is calling, as shown.
static PHONE_NUMBER: std::sync::Mutex<String> = std::sync::Mutex::new(String::new());

/// Your dial plan's normalization rules (Teams' dialPlanPolicy), once read.
static DIAL_PLAN: std::sync::RwLock<Option<teams_cli::calling::phone_audio::DialPlan>> = std::sync::RwLock::new(None);

fn dial_plan() -> teams_cli::calling::phone_audio::DialPlan {
    DIAL_PLAN.read().ok().and_then(|p| p.clone()).unwrap_or_default()
}

/// Read your dial plan (effective policy tenantDialPlan) once.
async fn load_dial_plan() {
    if DIAL_PLAN.read().is_ok_and(|p| p.is_some()) {
        return;
    }
    let r = async {
        let client = TeamsClient::new().await?;
        api::custom_emoji::effective_policies(&client, &["tenantDialPlan"]).await
    }
    .await;
    match r {
        Ok(v) => {
            let policy = v.pointer("/tenantDialPlan/value").cloned().unwrap_or_default();
            let plan = teams_cli::calling::phone_audio::DialPlan::from_policy(&policy);
            tracing::info!(rules = plan.has_rules(), "dial plan");
            if let Ok(mut w) = DIAL_PLAN.write() {
                *w = Some(plan);
            }
        }
        Err(e) => tracing::warn!("dial plan: {}", short_error(&e)),
    }
}

impl JoinedView {
    fn of(call: &OutgoingCall) -> Self {
        Self {
            invite: call.invite_url().unwrap_or_default().to_string(),
            capability: call.capability(),
            processing: call.processing(),
            ai_indicator: call.shows_ai_indicator(),
            has_audio: call.has_audio(),
            can_dtmf: call.can_dtmf(),
            can_video: call.can_send_video(),
            can_share: call.can_share(),
            started: call.meeting_started(),
            timers: call.timers().clone(),
            phone: phone_json(call, "", "", ""),
            event: event_json(&call.event(), "", ""),
            stream: call.streaming().then(|| (call.stream().cloned(), call.in_lobby())),
            breakout: call
                .joined_details()
                .and_then(teams_cli::calling::breakout::assigned_rooms_at_join)
                .map(|rooms| serde_json::to_string(&rooms).unwrap_or_default())
                .unwrap_or_default(),
        }
    }
}

/// The next meeting join asks for the attendee role (Preview as Attendee).
static JOIN_AS_ATTENDEE: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// call_stream_json's text.
fn stream_json(lobby: bool, url: &str, player: &str) -> String {
    serde_json::json!({ "lobby": lobby, "url": url, "player": player }).to_string()
}

/// The loopback server playing the town hall we watch, and the stream it serves.
static STREAM_PROXY: std::sync::Mutex<Option<(String, teams_cli::calling::live_stream::StreamProxy)>> = std::sync::Mutex::new(None);

fn stop_stream_proxy() {
    if let Ok(mut p) = STREAM_PROXY.lock() {
        *p = None;
    }
}

/// Serve the offered stream to the call window's player (a new server when
/// the stream's address changes) and tell the window.
fn update_stream(
    choice: Option<teams_cli::calling::live_stream::StreamChoice>,
    lobby: bool,
    qt: cxx_qt::CxxQtThread<qobject::Backend>,
) {
    runtime().spawn(async move {
        let first = choice.as_ref().and_then(|c| c.url().map(str::to_string)).unwrap_or_default();
        let player = choice.as_ref().map(|c| c.player_type.clone()).unwrap_or_default();
        let current = STREAM_PROXY.lock().ok().and_then(|p| p.as_ref().map(|(u, s)| (u.clone(), s.url.clone())));
        let url = match (current, choice) {
            (Some((u, local)), _) if u == first && !first.is_empty() => local,
            (_, Some(c)) if !first.is_empty() => match teams_cli::calling::live_stream::StreamProxy::start(&c).await {
                Ok(p) => {
                    tracing::info!(player = %player, "town hall stream: serving it to the player");
                    let local = p.url.clone();
                    if let Ok(mut slot) = STREAM_PROXY.lock() {
                        *slot = Some((first.clone(), p));
                    }
                    local
                }
                Err(e) => {
                    tracing::warn!("town hall stream: {}", short_error(&e));
                    String::new()
                }
            },
            _ => String::new(),
        };
        let text = stream_json(lobby, &url, &player);
        let _ = qt.queue(move |mut this| this.as_mut().set_call_stream_json(QString::from(text.as_str())));
    });
}

/// call_event_json: the meeting's event facts ("" when it isn't a town
/// hall or webinar and has no green room), what's being done and what
/// failed.
fn event_json(e: &teams_cli::calling::live_event::LiveEvent, busy: &str, failed: &str) -> String {
    if !e.is_event() && !e.staging {
        return String::new();
    }
    let mut v = serde_json::to_value(e).unwrap_or_default();
    v["eventPhase"] = serde_json::json!(e.event_phase());
    v["managed"] = serde_json::json!(e.managed());
    v["preview"] = serde_json::json!(e.preview());
    v["busy"] = serde_json::json!(busy);
    v["failed"] = serde_json::json!(failed);
    v.to_string()
}

/// Leave the meeting we moved out of (its media is already off).
/// Leave a preheated call, or withdraw it while it's being placed.
fn dispose_preheat(mut p: Preheat) {
    if let Some(cancel) = p.cancel.take() {
        let _ = cancel.send(());
    }
    let call = p.call.take();
    runtime().spawn(async move {
        // Its conversation ending as we leave is its own, not a call's.
        call_slot().lock().await.left_tags.push(p.tag.clone());
        if let Some(call) = call {
            match call.leave().await {
                Ok(()) => tracing::info!("left the preheated call"),
                Err(e) => tracing::warn!("leaving the preheated call: {}", short_error(&e)),
            }
        }
    });
}

/// The pre-join window opened for a meeting: join it hidden as Teams'
/// preheat does, and tell the window whether it offers Phone audio as
/// Teams' pre-join decides it (teams_cli::calling::phone_audio::
/// prejoin_pstn): from the meeting's latest details once they can tell,
/// else 15 s after the window opened from whether it allows PSTN
/// conferencing. The call stays until Join now or Cancel, or a minute
/// (Teams then leaves it).
async fn preheat_for_prejoin(qt: cxx_qt::CxxQtThread<qobject::Backend>, url: String, link: outgoing::MeetingLink) {
    use teams_cli::calling::phone_audio::{PSTN_CAPABILITIES_TIMEOUT, has_meeting_details, prejoin_fallback, prejoin_pstn};
    let opened = tokio::time::Instant::now();
    let tag = outgoing::new_call_tag();
    let stop = std::sync::Arc::new(tokio::sync::Notify::new());
    let (cancel_tx, cancel_rx) = tokio::sync::oneshot::channel();
    {
        let mut slot = call_slot().lock().await;
        if let Some(old) = slot.preheat.take() {
            old.stop.notify_one();
            dispose_preheat(old);
        }
        slot.preheat = Some(Preheat { url, tag: tag.clone(), call: None, cancel: Some(cancel_tx), stop: stop.clone(), breakout: None, joining: false });
    }
    let ours = |slot: &CallSlot| slot.preheat.as_ref().is_some_and(|p| p.tag == tag);
    let publish = |available: bool, how: &'static str| {
        let tag = tag.clone();
        let qt = qt.clone();
        async move {
            if !call_slot().lock().await.preheat.as_ref().is_some_and(|p| p.tag == tag) {
                return;
            }
            tracing::info!(available, how, "pre-join phone audio");
            let json = serde_json::json!({ "checked": true, "available": available }).to_string();
            let _ = qt.queue(move |mut this| this.as_mut().set_prejoin_phone_json(QString::from(json.as_str())));
        }
    };
    let mut events = teams_cli::event_hub::subscribe();
    tracing::info!("pre-join: preheating the meeting's call");
    let start = outgoing::preheat_meeting(&link, &tag, cancel_rx);
    tokio::pin!(start);
    let mut placed = false;
    let mut decided = false;
    let mut latest: Option<serde_json::Value> = None;
    let mut expires: Option<tokio::time::Instant> = None;
    let fallback_at = opened + PSTN_CAPABILITIES_TIMEOUT;
    loop {
        tokio::select! {
            r = &mut start, if !placed => {
                placed = true;
                let mut slot = call_slot().lock().await;
                match r {
                    Ok(call) if ours(&*slot) => {
                        tracing::info!(in_lobby = call.in_lobby(), "pre-join: the call is preheated");
                        if let Some(d) = call.joined_details() {
                            latest = Some(d.clone());
                        }
                        // A town hall we present in: Teams' split Join now.
                        let e = call.event();
                        let ev = if e.streaming && !call.streaming() {
                            let me = teams_cli::config::Config::load().ok().and_then(|c| c.object_id()).unwrap_or_default();
                            let organizer = call.organizer_oid().is_some_and(|o| o.eq_ignore_ascii_case(&me));
                            serde_json::json!({ "joinAs": if organizer { "Organizer" } else { "Presenter" } }).to_string()
                        } else {
                            String::new()
                        };
                        let _ = qt.queue(move |mut this| this.as_mut().set_prejoin_event_json(QString::from(ev.as_str())));
                        if let Some(p) = slot.preheat.as_mut() {
                            p.cancel = None;
                            p.call = Some(call);
                        }
                        expires = Some(tokio::time::Instant::now() + PREHEAT_TIMEOUT);
                    }
                    Ok(call) => {
                        // Cancelled while it was being placed.
                        drop(slot);
                        if let Err(e) = call.leave().await {
                            tracing::warn!("leaving the withdrawn preheated call: {}", short_error(&e));
                        }
                        return;
                    }
                    Err(e) => {
                        tracing::info!("pre-join: preheat failed: {}", short_error(&e));
                        if let Some(p) = slot.preheat.as_mut().filter(|p| p.tag == tag) {
                            p.cancel = None;
                        }
                    }
                }
                drop(slot);
                if !decided && let Some(available) = latest.as_ref().and_then(|d| prejoin_pstn(d, false)) {
                    decided = true;
                    publish(available, "details").await;
                }
                if decided && expires.is_none() {
                    return;
                }
            }
            ev = events.recv() => {
                let ev = match ev {
                    Ok(ev) => ev,
                    Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => continue,
                    Err(_) => return,
                };
                if ev.kind != teams_cli::event_hub::EventKind::Call {
                    continue;
                }
                let Ok(v) = serde_json::from_str::<serde_json::Value>(&ev.json) else { continue };
                if v["callTag"].as_str() != Some(tag.as_str()) {
                    continue;
                }
                if teams_cli::calling::incoming::is_call_end_event(&ev.json) && placed {
                    // The meeting ended it (or we left): nothing to keep.
                    tracing::info!("pre-join: the preheated call ended");
                    let mut slot = call_slot().lock().await;
                    if ours(&*slot) {
                        slot.preheat = None;
                        slot.left_tags.push(tag.clone());
                    }
                    expires = None;
                    if decided {
                        return;
                    }
                    continue;
                }
                if has_meeting_details(&v) {
                    latest = Some(v);
                    if !decided && let Some(available) = latest.as_ref().and_then(|d| prejoin_pstn(d, false)) {
                        decided = true;
                        publish(available, "details").await;
                    }
                }
            }
            _ = tokio::time::sleep_until(fallback_at), if !decided => {
                decided = true;
                publish(prejoin_fallback(latest.as_ref()), "fallback").await;
                if placed && expires.is_none() {
                    return;
                }
            }
            _ = tokio::time::sleep_until(expires.unwrap_or(opened)), if expires.is_some() => {
                // Teams leaves its preheated call after a minute.
                let p = {
                    let mut slot = call_slot().lock().await;
                    if ours(&*slot) { slot.preheat.take() } else { None }
                };
                if let Some(p) = p {
                    tracing::info!("pre-join: the preheated call timed out");
                    dispose_preheat(p);
                }
                expires = None;
                if decided {
                    return;
                }
            }
            // Joined or cancelled. While the call is still being placed,
            // its request is out: let it finish (the cancel withdraws it,
            // a late answer is left above) rather than drop it, which
            // would leave a preheated endpoint in the meeting.
            _ = stop.notified(), if placed => return,
        }
    }
}

/// A participant now in a breakout room: leave the main meeting as Teams
/// does (`POST links.leave`) and at once join its conversation again
/// without a call, so its updates keep coming and going back posts the
/// call straight to it (captured 2026-11-17).
async fn leave_and_keep_main(main: OutgoingCall, main_url: String) {
    let conversation = main.conversation_url();
    match main.leave_or_hang_up().await {
        Ok(()) => tracing::info!("left the main meeting for its breakout room"),
        Err(e) => tracing::warn!("leaving the main meeting: {}", short_error(&e)),
    }
    let (Some(conversation), Some(link)) = (conversation, outgoing::MeetingLink::parse(&main_url)) else {
        tracing::warn!("the main meeting's conversation is unknown; not kept");
        return;
    };
    match outgoing::keep_conversation(&main_url, &link, &conversation).await {
        Ok(kept) => {
            let mut slot = call_slot().lock().await;
            if let Some(old) = slot.kept_main.replace(kept) {
                drop(slot);
                if let Err(e) = old.leave().await {
                    tracing::warn!("leaving an older kept conversation: {}", short_error(&e));
                }
            }
        }
        Err(e) => tracing::warn!("keeping the main meeting's conversation: {}", short_error(&e)),
    }
}

/// The main meeting's kept conversation, when nothing went back to it
/// (the room ended or was left and we stayed out): leave it after a
/// while, as nothing will use it.
fn leave_kept_main_later() {
    runtime().spawn(async {
        let tag = match call_slot().lock().await.kept_main.as_ref() {
            Some(k) => k.call_tag().to_string(),
            None => return,
        };
        tokio::time::sleep(std::time::Duration::from_secs(30)).await;
        let mut slot = call_slot().lock().await;
        if slot.kept_main.as_ref().is_some_and(|k| k.call_tag() == tag)
            && let Some(k) = slot.kept_main.take()
        {
            drop(slot);
            match k.leave().await {
                Ok(()) => tracing::info!("left the unused kept main conversation"),
                Err(e) => tracing::warn!("leaving the kept main conversation: {}", short_error(&e)),
            }
        }
    });
}

async fn leave_moved_from(call: OutgoingCall) {
    match call.hang_up().await {
        Ok(()) => tracing::info!("left the meeting we moved out of"),
        Err(e) => tracing::warn!("leaving the meeting we moved out of: {}", short_error(&e)),
    }
}

fn call_slot() -> &'static tokio::sync::Mutex<CallSlot> {
    static SLOT: OnceLock<tokio::sync::Mutex<CallSlot>> = OnceLock::new();
    SLOT.get_or_init(Default::default)
}

/// A scheduled meeting's notes we claimed through Teams' collab object
/// service and are making: the meeting, who asked, the claim's secret and
/// the service's region (kept in memory only, until committed).
type NotesClaim = (api::meeting_notes::Meeting, api::meeting_notes::CollabCaller, String, String);
fn notes_claim() -> &'static tokio::sync::Mutex<Option<NotesClaim>> {
    static CLAIM: OnceLock<tokio::sync::Mutex<Option<NotesClaim>>> = OnceLock::new();
    CLAIM.get_or_init(Default::default)
}

/// The meeting artifacts service's region (Teams' regional `mcps`): the
/// region of the events service the tenant was given, else "us".
fn notes_region(client: &TeamsClient) -> String {
    api::events::regional_endpoint(client).rsplit('/').next().filter(|r| r.len() <= 8).unwrap_or("us").to_string()
}

/// Where our own RTT lines are kept apart from everyone else's (Teams
/// uses its own data source; ours is known only once the channel is up).
const OWN_RTT_SOURCE: u32 = u32::MAX;

/// Our RTT chunks, sent in the order typed by one task.
fn rtt_outbox() -> &'static tokio::sync::mpsc::UnboundedSender<String> {
    static OUTBOX: OnceLock<tokio::sync::mpsc::UnboundedSender<String>> = OnceLock::new();
    OUTBOX.get_or_init(|| {
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<String>();
        runtime().spawn(async move {
            while let Some(chunk) = rx.recv().await {
                let sent = call_slot()
                    .lock()
                    .await
                    .outgoing
                    .as_ref()
                    .is_some_and(|call| call.send_real_time_text(&chunk));
                if !sent {
                    tracing::warn!("real-time text: the call has no meeting data channel");
                }
            }
        });
        tx
    })
}

/// Log media health every 5 s while a call lasts.
/// Our side of someone's transfer or park (Teams' onTransferRequested):
/// place the call they asked for, carrying their transferor and context;
/// once it is answered tell them (transferAcceptance, then
/// transferCompletion code 0) and carry on in the new call; else report
/// the failure (code 500).
/// Teams Rooms' handling of an incoming call (RigelCallHandler's
/// onCallStateNotified, then byomAutoAcceptService.acceptCall): fetch the
/// full invitation (its invitationData), decide within Teams' 4 seconds,
/// then accept by itself (the microphone on, the camera when video is
/// allowed; a meeting's invitation joins as a meeting) or ring on the
/// room's console for someone in the room to answer.
async fn room_incoming(
    qt: cxx_qt::CxxQtThread<qobject::Backend>,
    call_id: Option<String>,
    peer: String,
    peer_id: String,
    video: bool,
) {
    use teams_cli::calling::room_mode::Decision;
    let (conference, thread) = {
        let slot = call_slot().lock().await;
        match slot.ringing.as_ref().filter(|c| c.call_id() == call_id) {
            Some(c) => (c.is_conference(), c.thread_id()),
            None => return,
        }
    };
    let auto_exit = teams_cli::calling::room_mode::auto_exits_when_alone(thread.as_deref());
    let checked = tokio::time::timeout(std::time::Duration::from_secs(4), async {
        let auth = CallAuth::load().await.ok();
        let mut slot = call_slot().lock().await;
        let call = slot.ringing.as_mut().filter(|c| c.call_id() == call_id)?;
        if let Some(auth) = auth {
            auth.probe_video(call).await;
        }
        let tenant = teams_cli::config::Config::load().ok().and_then(|c| c.tenant_id());
        Some((crate::room_host::decide(call, tenant.as_deref()), call.has_video(), call.meeting_details().cloned()))
    })
    .await;
    let (decision, offered, details) = match checked {
        Ok(Some(d)) => d,
        // Taken or gone meanwhile.
        Ok(None) => return,
        Err(_) => {
            tracing::info!("room mode: auto-accept timed out");
            (Decision::Ring("Timed_out"), video, None)
        }
    };
    // Teams Rooms' auto exit goes by the meeting's details (its type and
    // schedule; a channel's Meet now is ad hoc too); without them, by its
    // chat.
    let kind = details.as_ref().map(teams_cli::calling::room_mode::meeting_kind);
    if let Some(d) = &details {
        let keys: Vec<&String> = d.as_object().map(|o| o.keys().collect()).unwrap_or_default();
        let (meeting_type, end_time) = (d.get("meetingType").cloned(), d.get("endTime").cloned());
        tracing::info!(?kind, ?meeting_type, ?end_time, ?keys, "room mode: meeting details");
    }
    let auto_exit = match &kind {
        Some(k) => k.adhoc,
        None => auto_exit,
    };
    // Teams Rooms' title for the call: from its conversation (the chat's
    // topic and kind, else who else is in it).
    let (title, thread_meeting) = match tokio::time::timeout(
        std::time::Duration::from_secs(4),
        room_call_title(thread.as_deref(), &peer, &peer_id),
    )
    .await
    {
        Ok(t) => t,
        Err(_) => (
            teams_cli::calling::room_mode::call_title(&teams_cli::calling::room_mode::CallConversation {
                others: vec![peer.clone()],
                ..Default::default()
            }),
            None,
        ),
    };
    // Without the invitation's meeting details, the chat's meeting.
    let auto_exit = match (&kind, &thread_meeting) {
        (None, Some(m)) if !m.meeting_type.is_empty() => m.meeting_type == "Adhoc",
        _ => auto_exit,
    };
    let meeting_end = kind
        .and_then(|k| k.end)
        .or_else(|| thread_meeting.as_ref().map(|m| m.end.clone()).filter(|e| !e.is_empty() && !e.starts_with("0001-")))
        .unwrap_or_default();
    tracing::info!(%title, %meeting_end, auto_exit, "room mode: call title");
    let accept = match decision {
        Decision::Accept { video } => Some(video),
        Decision::Ring(reason) => {
            tracing::info!(reason, "room mode: ringing on the console");
            None
        }
    };
    let _ = qt.queue(move |mut this| {
        this.as_mut().set_call_peer(QString::from(peer.as_str()));
        this.as_mut().set_call_peer_id(QString::from(peer_id.as_str()));
        this.as_mut().set_call_video_offered(offered);
        this.as_mut().set_call_meeting(conference);
        this.as_mut().set_call_scheduled(false);
        this.as_mut().set_call_adhoc_meeting(false);
        this.as_mut().rust_mut().roster.clear();
        this.as_mut().rust_mut().room_auto_exit = auto_exit;
        this.as_mut().set_room_meeting_end(QString::from(meeting_end.as_str()));
        // The meeting's chat: its calendar entry (end time) for Teams Rooms'
        // end-of-meeting auto exit.
        this.as_mut().set_call_thread_id(QString::from(thread.as_deref().unwrap_or_default()));
        this.as_mut().rust_mut().room_saw_others = false;
        this.as_mut().rust_mut().room_escalated = false;
        this.as_mut().rust_mut().room_call_title = title;
        this.as_mut().set_call_state(QString::from("ringing"));
        if let Some(video) = accept {
            tracing::info!(video, conference, "room mode: auto-accepting");
            this.as_mut().accept_call(video);
        }
    });
}

/// Teams Rooms' title for a call in `thread` from `caller`: the thread's
/// topic and kind (chat service thread properties), else its other
/// members' names ([`teams_cli::calling::room_mode::call_title`]).
async fn room_call_title(thread: Option<&str>, caller: &str, caller_id: &str) -> (String, Option<api::ThreadMeeting>) {
    use teams_cli::calling::room_mode::{call_title, conversation_kind, CallConversation, ConversationKind};
    let mut conv = CallConversation { others: vec![caller.to_string()], ..Default::default() };
    let Some(thread) = thread.filter(|t| t.starts_with("19:")) else {
        return (call_title(&conv), None);
    };
    let client = match TeamsClient::new().await {
        Ok(c) => c,
        Err(_) => return (call_title(&conv), None),
    };
    let props = api::tab_add::thread_properties(&client, thread).await;
    let kind = match &props {
        Ok(p) => conversation_kind(thread, p.get("threadType").and_then(|v| v.as_str())),
        Err(e) => {
            tracing::info!("room mode: the call's chat: {}", short_error(e));
            conversation_kind(thread, None)
        }
    };
    conv.kind = Some(kind);
    // The thread's meeting (Teams Rooms' getMeetingDetails: its type and
    // scheduled end, and a meeting chat's subject).
    let meeting = props.as_ref().ok().and_then(api::thread_meeting);
    if let Ok(p) = &props {
        conv.topic = p
            .get("topic")
            .or_else(|| p.get("spaceThreadTopic"))
            .and_then(|v| v.as_str())
            .filter(|t| !t.trim().is_empty())
            .map(str::to_string)
            .or_else(|| meeting.as_ref().map(|m| m.subject.clone()).filter(|_| kind == ConversationKind::PrivateMeeting));
        conv.huddle = p.get("conversationType").and_then(|v| v.as_str()) == Some("huddleGroupCall");
        let keys: Vec<&String> = p.as_object().map(|o| o.keys().collect()).unwrap_or_default();
        tracing::info!(?kind, ?keys, "room mode: the call's chat");
    }
    if conv.topic.is_none() && matches!(kind, ConversationKind::Group | ConversationKind::Other) {
        let me = client.object_id().map(|o| format!("8:orgid:{o}").to_ascii_lowercase()).unwrap_or_default();
        match api::chat_members(&client, thread).await {
            Ok(members) => {
                let others: Vec<String> = members
                    .into_iter()
                    .filter(|m| !m.me && m.mri != me && !m.name.is_empty())
                    .map(|m| m.name)
                    .collect();
                if !others.is_empty() {
                    conv.others = others;
                }
            }
            Err(_) if !caller_id.is_empty() => conv.others = vec![caller.to_string()],
            Err(_) => {}
        }
    }
    (call_title(&conv), meeting)
}

async fn take_transfer(qt: cxx_qt::CxxQtThread<qobject::Backend>, request: teams_cli::calling::incoming::TransferRequest) {
    let auth = match CallAuth::load().await {
        Ok(a) => a,
        Err(e) => {
            tracing::warn!("transfer: {}", short_error(&e));
            return;
        }
    };
    let my_oid = teams_cli::config::Config::load().ok().and_then(|c| c.object_id()).unwrap_or_default();
    let target_oid = request.target_mri.strip_prefix("8:orgid:").unwrap_or_default().to_string();
    let chat = outgoing::one_to_one_chat_id(&my_oid, &target_oid).unwrap_or_default();
    let extras = teams_cli::calling::signaling::CallExtras {
        transferor: Some(request.transferor.clone()),
        transfer_context: request.transfer_context.clone(),
        unpark_code: None,
        voicemail: None,
    };
    let tag = outgoing::new_call_tag();
    let (_cancel_tx, cancel_rx) = tokio::sync::oneshot::channel();
    let result = outgoing::place_transfer_call(&chat, &request.target_mri, &extras, &tag, cancel_rx).await;
    match result {
        Ok(call) => {
            tracing::info!("transferred call connected");
            if let Some(link) = &request.acceptance_link
                && let Err(e) = teams_cli::calling::incoming::answer_transfer_request(&auth, link, None).await
            {
                tracing::warn!("transfer acceptance: {}", short_error(&e));
            }
            if let Some(link) = &request.completion_link
                && let Err(e) = teams_cli::calling::incoming::answer_transfer_request(&auth, link, Some(0)).await
            {
                tracing::warn!("transfer completion: {}", short_error(&e));
            }
            let e2ee = call.is_e2ee();
            let e2ee_numbers = call.e2ee_numbers().join(" ");
            let answered_by = call.answered_by().map(str::to_string);
            let mut slot = call_slot().lock().await;
            // The call we leave ends on its own; its events aren't ours.
            if slot.active.take().is_some() {
                slot.superseded_untagged = true;
            }
            if let Some(old) = slot.outgoing.take() {
                slot.left_tags.push(old.call_tag().to_string());
            }
            slot.outgoing = Some(call);
            drop(slot);
            // Teams' request may not name the target: then who answered.
            let name = Some(request.target_name.clone())
                .filter(|n| !n.trim().is_empty())
                .or_else(|| answered_by.clone())
                .unwrap_or_default();
            let mri = request.target_mri.clone();
            let _ = qt.queue(move |mut this| {
                this.as_mut().set_call_continues(true);
                this.as_mut().set_call_held(false);
                this.as_mut().set_call_held_by_peer(false);
                this.as_mut().set_call_e2ee(e2ee);
                this.as_mut().set_call_e2ee_numbers(QString::from(e2ee_numbers.as_str()));
                this.as_mut().set_call_peer(QString::from(name.as_str()));
                this.as_mut().set_call_peer_id(QString::from(mri.as_str()));
            });
        }
        Err(e) => {
            tracing::warn!("transferred call failed: {}", short_error(&e));
            if let Some(link) = &request.completion_link {
                let _ = teams_cli::calling::incoming::answer_transfer_request(&auth, link, Some(500)).await;
            }
        }
    }
}

/// What [`qobject::Backend::place_and_show`] places.
enum Placement {
    /// A 1:1 call in this chat.
    Person { chat_id: String, callee: String, video: bool },
    /// Retrieving a parked call with its pickup code.
    Unpark(i64),
    /// Your own voicemail, to record your greeting.
    Voicemail,
}

/// Hold (or resume) the first call while a consult goes on.
async fn set_first_held(slot: &mut CallSlot, held: bool) -> anyhow::Result<()> {
    match (slot.active.as_mut(), slot.outgoing.as_mut()) {
        (Some(call), _) => call.hold(&CallAuth::load().await?, held).await,
        (None, Some(call)) => call.hold(held).await,
        _ => Err(anyhow::anyhow!("No call")),
    }
}

/// Show the consult as it stands in the call window.
fn publish_consult(qt: &cxx_qt::CxxQtThread<qobject::Backend>, slot: &CallSlot) {
    let view = slot.consult_state.view();
    let text = if view.is_null() { String::new() } else { view.to_string() };
    let _ = qt.queue(move |mut this| this.as_mut().set_call_consult_json(QString::from(text.as_str())));
}

/// The consult call is over (they hung up or didn't answer, or you ended
/// it): back to the held call, as Teams' Resume.
async fn consult_ended(qt: &cxx_qt::CxxQtThread<qobject::Backend>, slot: &mut CallSlot) {
    use teams_cli::calling::consult::{Action, Event};
    let (next, action) = slot.consult_state.step(Event::ConsultEnded);
    slot.consult_state = next;
    if action == Action::ResumeFirst {
        slot.consult_tag = None;
        slot.consult = None;
        if let Err(e) = set_first_held(slot, false).await {
            tracing::warn!("resume after consult: {}", short_error(&e));
        }
        let _ = qt.queue(|mut this| this.as_mut().set_call_held(false));
    }
    publish_consult(qt, slot);
}

/// Whether Teams would offer you Park Call in this call (your park policy
/// and Enterprise Voice), read as the call connects.
fn spawn_call_park_check(qt: cxx_qt::CxxQtThread<qobject::Backend>) {
    runtime().spawn(async move {
        let park = async { api::preferences::call_park_available(&TeamsClient::new().await?).await }.await;
        match park {
            Ok(on) => {
                tracing::info!(on, "call park available");
                let _ = qt.queue(move |mut this| this.as_mut().set_call_can_park(on));
            }
            Err(e) => tracing::warn!("call park: {}", short_error(&e)),
        }
    });
}

fn spawn_call_stats_logger(qt: cxx_qt::CxxQtThread<qobject::Backend>) {
    spawn_call_park_check(qt.clone());
    runtime().spawn(async move {
        let mut tick = 0u64;
        let mut muted_speech = teams_cli::calling::muted_speech::Detector::new();
        // Call health's 15 s window starts with the call.
        *health_sampler().lock().unwrap_or_else(|e| e.into_inner()) =
            teams_cli::calling::call_health::Sampler::new();
        let mut speaking_muted = false;
        loop {
            tokio::time::sleep(std::time::Duration::from_secs(1)).await;
            tick += 1;
            health_sampler().lock().unwrap_or_else(|e| e.into_inner()).sample(
                &teams_cli::calling::call_health::current(),
                chrono::Utc::now().timestamp_millis(),
            );
            // Talking with the mic off (Teams checks with each stats poll).
            let muted = {
                let slot = call_slot().lock().await;
                match (slot.active.as_ref(), slot.outgoing.as_ref()) {
                    (Some(call), _) => Some(call.is_muted()),
                    (None, Some(call)) => Some(call.is_muted() || call.is_server_muted()),
                    (None, None) => None,
                }
            };
            if let Some(muted) = muted {
                let signal = teams_cli::calling::audio::take_mic_signal();
                let strength = {
                    let slot = call_slot().lock().await;
                    slot.outgoing.as_ref().map(|c| c.network_strength())
                };
                if let (Some(w), Some(strength)) =
                    (echo_watch().lock().unwrap_or_else(|e| e.into_inner()).as_mut(), strength)
                {
                    w.second(muted, signal, strength);
                    w.devices(&teams_cli::calling::device_health::devices());
                }
                let now = muted_speech.report(muted, teams_cli::calling::audio::mic_recent_level());
                if now != speaking_muted {
                    speaking_muted = now;
                    tracing::info!(speaking_muted = now, "speaking while muted");
                    let _ = qt.queue(move |mut this| this.as_mut().set_call_speaking_while_muted(now));
                }
            }
            // Teams' network strength (your name tag's bars), each second.
            let strength = {
                let slot = call_slot().lock().await;
                if let Some(call) = slot.active.as_ref() {
                    Some(call.network_strength())
                } else {
                    slot.outgoing.as_ref().map(|c| c.network_strength())
                }
            };
            let Some(strength) = strength else {
                if speaking_muted {
                    let _ = qt.queue(|mut this| this.as_mut().set_call_speaking_while_muted(false));
                }
                return;
            };
            let name = strength.name();
            let _ = qt.queue(move |mut this| {
                if this.rust().call_network_strength.to_string() != name {
                    this.as_mut().set_call_network_strength(QString::from(name));
                }
            });
            if tick % 5 != 0 {
                continue;
            }
            let slot = call_slot().lock().await;
            if let Some(call) = slot.active.as_ref() {
                if let Some(s) = call.audio_stats().await {
                    tracing::info!(
                        sent = s.packets_sent,
                        received = s.packets_received,
                        muted = call.is_muted(),
                        "call audio"
                    );
                }
            } else if let Some(call) = slot.outgoing.as_ref() {
                if let Some(s) = call.stats().await {
                    tracing::info!(
                        sent = s.packets_sent,
                        received = s.packets_received,
                        undecryptable = s.packets_undecryptable,
                        muted = call.is_muted(),
                        audio_bytes = s.audio_bytes_sent,
                        played_peak = teams_cli::calling::audio::take_speaker_peak(),
                        mic = teams_cli::calling::audio::mic_level(),
                        mic_out = teams_cli::calling::audio::take_mic_out_peak(),
                        "call audio"
                    );
                }
            } else {
                return;
            }
        }
    });
}

/// Call health's samples of the call in progress.
/// The conversation the Forward and Share pickers' choices go to: a picked
/// chat or channel; one person's 1:1; several people's group chat (an
/// existing one with exactly those members, else a new one).
async fn picked_conversation(
    client: &TeamsClient,
    targets: &[serde_json::Value],
    group_chats: &[String],
) -> anyhow::Result<String> {
    let me = client
        .object_id()
        .ok_or_else(|| anyhow::anyhow!("not signed in"))?;
    let chats: Vec<&serde_json::Value> = targets.iter().filter(|t| t["kind"] == "chat").collect();
    let people: Vec<String> = targets
        .iter()
        .filter(|t| t["kind"] == "person")
        .filter_map(|t| t["oid"].as_str().map(str::to_string))
        .collect();
    if let Some(c) = chats.first() {
        return Ok(c["id"].as_str().unwrap_or_default().to_string());
    }
    if people.is_empty() {
        anyhow::bail!("Nobody to send to");
    }
    if people.len() == 1 {
        return api::ensure_one_on_one_chat(
            client,
            &format!("8:orgid:{me}"),
            &format!("8:orgid:{}", people[0]),
        )
        .await;
    }
    let mut want: Vec<String> = people
        .iter()
        .chain(std::iter::once(&me))
        .map(|o| format!("8:orgid:{}", o.to_ascii_lowercase()))
        .collect();
    want.sort();
    want.dedup();
    for chat in group_chats {
        if let Ok(mut members) = api::thread_member_ids(client, chat).await {
            members.sort();
            if members == want {
                return Ok(chat.clone());
            }
        }
    }
    api::create_group_chat(client, &want, "").await
}

