/// The camera a call would use, (path, name): the one chosen in Settings
/// > Devices, else the first camera, as the test call report names it.
fn test_camera() -> Option<(String, String)> {
    let cameras = teams_cli::calling::camera::list_devices();
    match camera_device() {
        Some(path) => cameras.into_iter().find(|c| c.0 == path),
        None => cameras.into_iter().next(),
    }
}

/// The camera chosen in Settings > Devices (a V4L2 path), else the default;
/// your avatar while it is on (Teams selects the avatar as the camera).
fn camera_device() -> Option<String> {
    if ost_vfx::avatar::active() {
        return Some(teams_cli::calling::camera::AVATAR_DEVICE.to_string());
    }
    // OST_CAMERA_DEVICE=/dev/videoN: this instance's camera (tests on a
    // machine other instances share, whose settings file is common).
    if let Some(d) = std::env::var("OST_CAMERA_DEVICE").ok().filter(|d| d.starts_with("/dev/video")) {
        return Some(d);
    }
    load_settings()
        .get("cameraDevice")
        .and_then(|v| v.as_str())
        .filter(|d| d.starts_with("/dev/video") && d[10..].bytes().all(|b| b.is_ascii_digit()))
        .map(str::to_string)
}

/// Whether OST draws Teams' banners itself (src/native.cpp knows how to
/// place its window here); else the desktop's notifications are used.
/// OST_SYSTEM_NOTIFICATIONS=1 asks for the desktop's.
fn banners_available() -> bool {
    static SUPPORT: OnceLock<bool> = OnceLock::new();
    *SUPPORT.get_or_init(|| {
        std::env::var_os("OST_SYSTEM_NOTIFICATIONS").is_none()
            // SAFETY: called on the Qt thread, once the application exists.
            && unsafe { ost_banner_support() } > 0
    })
}

/// Someone's short name for group chat banners (Teams' rule,
/// api::directory::short_name), from their profile, remembered.
async fn sender_short_name(mri: &str, display: &str) -> String {
    static NAMES: OnceLock<std::sync::Mutex<std::collections::HashMap<String, String>>> = OnceLock::new();
    let names = NAMES.get_or_init(Default::default);
    if let Some(n) = names.lock().ok().and_then(|n| n.get(mri).cloned()) {
        return n;
    }
    let record = async {
        let client = TeamsClient::new().await?;
        api::directory::short_profile_records(&client, &[mri.to_string()]).await
    }
    .await
    .ok()
    .and_then(|r| r.into_iter().next());
    let Some(p) = record else { return display.to_string() };
    let field = |k: &str| p[k].as_str().unwrap_or_default().to_string();
    let full = Some(field("displayName")).filter(|d| !d.is_empty()).unwrap_or_else(|| display.to_string());
    let short = api::directory::short_name(&app_locale(), &field("surname"), &field("givenName"), &full);
    if let Ok(mut n) = names.lock() {
        n.insert(mri.to_string(), short.clone());
    }
    short
}

