    pub fn headset_state(&self, prejoin: bool, prejoin_muted: bool) {
        let state = self.call_state.to_string();
        // Teams' appState: hooked until a call connects (a ringing call is
        // still on hook, "pulsing").
        let hooked = matches!(state.as_str(), "" | "ended" | "ringing");
        teams_cli::calling::hid_telephony::set_app_state(teams_cli::calling::hid_telephony::AppState {
            hooked,
            ringing: state == "ringing",
            muted: !hooked && self.call_muted,
            in_prejoin: prejoin,
            prejoin_muted,
            held: !hooked && self.call_held,
        });
        // The Bluetooth headset's view of the call, and the app's mute as
        // its microphone gain (Teams' VoIP call coordinator reports).
        use std::sync::atomic::Ordering;
        match state.as_str() {
            "ringing" => HFP_INCOMING.store(true, Ordering::SeqCst),
            "calling" => HFP_INCOMING.store(false, Ordering::SeqCst),
            _ => {}
        }
        let incoming = HFP_INCOMING.load(Ordering::SeqCst);
        let phase = teams_cli::calling::hfp::Phase::of(&state, self.call_held, incoming);
        crate::hfp_calls::set_call(crate::hfp_calls::CallView { phase, incoming, peer: self.call_peer.to_string() });
        let in_call = matches!(state.as_str(), "calling" | "connecting" | "connected" | "lobby");
        let muted = in_call && self.call_muted;
        teams_cli::calling::hfp::sync_app_mute(in_call, muted);
    }

    pub fn headset_status(&self) -> QString {
        QString::from(serde_json::to_string(&teams_cli::calling::hid_telephony::status()).unwrap_or_default().as_str())
    }

    pub fn headset_take_control(&self) {
        teams_cli::calling::hid_telephony::take_control();
    }

    /// A headset button, as Teams' HID service acts on it.
    fn on_headset_action(mut self: Pin<&mut Self>, action: teams_cli::calling::hid_telephony::Action) {
        use teams_cli::calling::hid_telephony::{Action, AspEvent};
        let state = self.call_state.to_string();
        let in_call = matches!(state.as_str(), "calling" | "connecting" | "connected" | "lobby");
        tracing::info!(?action, state = %state, "headset button");
        match action {
            Action::Answer if state == "ringing" => self.accept_call(false),
            Action::Reject if state == "ringing" => self.decline_call(),
            Action::HangUp if in_call => self.hang_up(),
            Action::SetMuted(muted) => {
                if in_call {
                    if self.call_muted != muted {
                        self.toggle_mute();
                    }
                } else {
                    self.as_mut().headset_prejoin_mute(muted);
                }
            }
            Action::ToggleHold if state == "connected" => self.toggle_hold(),
            Action::TeamsButton { long: true, .. } => {
                // Teams' long press raises or lowers your hand in a
                // meeting that isn't on hold.
                if state == "connected" && self.call_meeting && !self.call_held {
                    self.toggle_hand();
                } else {
                    tracing::info!("headset: Teams button long press with no meeting");
                }
            }
            Action::TeamsButton { event, long: false } => {
                let what = match event {
                    AspEvent::MissedCall => "calls",
                    AspEvent::Voicemail => "voicemail",
                    _ => "front",
                };
                // Viewing it clears the device's notification.
                if matches!(event, AspEvent::MissedCall | AspEvent::Voicemail) {
                    teams_cli::calling::hid_telephony::push_notification(AspEvent::None);
                }
                self.as_mut().headset_teams_button(QString::from(what));
            }
            Action::TransferPrompt => self.as_mut().headset_transfer_prompt(),
            _ => tracing::info!("headset: nothing to do now"),
        }
    }

    pub fn toggle_hand(mut self: Pin<&mut Self>) {
        let up = !self.rust().call_hand_raised;
        self.as_mut().set_call_hand_raised(up);
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let mut slot = call_slot().lock().await;
            let result = match slot.outgoing.as_mut() {
                Some(call) => call.raise_hand(up).await,
                None => Err(anyhow::anyhow!("Raise hand is for meetings")),
            };
            drop(slot);
            if let Err(e) = result {
                tracing::warn!("raise hand: {}", short_error(&e));
                let _ = qt.queue(move |mut this| {
                    this.as_mut().set_call_hand_raised(!up);
                    this.as_mut().set_status_text(QString::from(
                        if up {
                            tr("Couldn't raise your hand. Try again.")
                        } else {
                            tr("Couldn't lower your hand. Try again.")
                        }
                        .as_str(),
                    ));
                });
            }
        });
    }

    /// Sign language mode in the meeting: publish `kind` ("dhhSigner" or
    /// "signLanguageInterpreter") with its content, or take it back ("").
    pub fn set_sign_language_state(mut self: Pin<&mut Self>, kind: &QString, content_json: &QString) {
        let kind = kind.to_string();
        // Teams detects signing only for a Signer (isVideoDHHSigner).
        self.as_mut().rust_mut().sign_signer = kind == "dhhSigner";
        if !self.rust().sign_ticker {
            self.as_mut().rust_mut().sign_ticker = true;
            let qt = self.qt_thread();
            runtime().spawn(async move {
                let mut every = tokio::time::interval(std::time::Duration::from_millis(500));
                loop {
                    every.tick().await;
                    if qt.queue(|this| this.sign_detection_tick()).is_err() {
                        break;
                    }
                }
            });
        }
        let content: serde_json::Value = serde_json::from_str(&content_json.to_string()).unwrap_or_else(|_| json!({}));
        runtime().spawn(async move {
            let mut slot = call_slot().lock().await;
            let result = match slot.outgoing.as_mut() {
                Some(call) => call.sign_language_state((!kind.is_empty()).then_some((kind.as_str(), content))).await,
                None => Ok(()),
            };
            if let Err(e) = result {
                tracing::warn!("sign language state: {}", short_error(&e));
            }
        });
    }

    pub fn transfer_call(self: Pin<&mut Self>, oid: &QString) {
        let target = format!("8:orgid:{}", oid.to_string().trim());
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let slot = call_slot().lock().await;
            let result = match (slot.active.as_ref(), slot.outgoing.as_ref()) {
                (Some(call), _) => match CallAuth::load().await {
                    Ok(auth) => call.transfer(&auth, &target, None).await,
                    Err(e) => Err(e),
                },
                (None, Some(call)) => call.transfer(&target, None).await,
                _ => Err(anyhow::anyhow!("No call")),
            };
            drop(slot);
            let text = match &result {
                Ok(()) => tr("Transferring..."),
                Err(e) => {
                    tracing::warn!("transfer: {}", short_error(e));
                    tr("Transfer failed")
                }
            };
            tracing::info!(ok = result.is_ok(), "transfer requested");
            let _ = qt
                .queue(move |mut this| this.as_mut().set_status_text(QString::from(text.as_str())));
        });
    }

    pub fn consult_call(mut self: Pin<&mut Self>, oid: &QString, name: &QString) {
        use teams_cli::calling::consult::{Action, Event, Person};
        let oid = oid.to_string().trim().to_ascii_lowercase();
        let name = name.to_string();
        let my_oid = teams_cli::config::Config::load().ok().and_then(|c| c.object_id()).unwrap_or_default();
        let Some(chat) = outgoing::one_to_one_chat_id(&my_oid, &oid) else {
            self.as_mut().set_status_text(QString::from(tr("Consult: not someone you can call")));
            return;
        };
        let mri = format!("8:orgid:{oid}");
        let was_held = self.rust().call_held;
        let qt = self.qt_thread();
        let tag = outgoing::new_call_tag();
        let (cancel_tx, cancel_rx) = tokio::sync::oneshot::channel();
        runtime().spawn(async move {
            {
                let mut slot = call_slot().lock().await;
                let (next, action) = slot.consult_state.step(Event::Start(Person { mri: mri.clone(), name }));
                if action != Action::HoldAndCall {
                    return;
                }
                slot.consult_state = next;
                slot.consult_tag = Some(tag.clone());
                slot.cancel_consult = Some(cancel_tx);
                if !was_held && let Err(e) = set_first_held(&mut slot, true).await {
                    tracing::warn!("consult hold: {}", short_error(&e));
                }
                publish_consult(&qt, &slot);
            }
            if !was_held {
                let _ = qt.queue(|mut this| this.as_mut().set_call_held(true));
            }
            tracing::info!("consult call placed");
            let result = outgoing::place_call_tagged(&chat, &mri, &tag, cancel_rx).await;
            let mut slot = call_slot().lock().await;
            slot.cancel_consult = None;
            match result {
                Ok(call) if matches!(slot.consult_state, teams_cli::calling::consult::Consult::Placing { .. }) => {
                    tracing::info!(replace = call.replace_link().is_some(), "consult call answered");
                    slot.consult = Some(call);
                    let (next, _) = slot.consult_state.step(Event::Answered);
                    slot.consult_state = next;
                    publish_consult(&qt, &slot);
                }
                Ok(call) => {
                    // The consult was ended while it rang.
                    drop(slot);
                    let _ = call.hang_up().await;
                }
                Err(e) => {
                    tracing::info!("consult call failed: {}", short_error(&e));
                    let msg = tr("Consult: %1").replace("%1", &short_error(&e));
                    consult_ended(&qt, &mut slot).await;
                    let _ = qt.queue(move |mut this| this.as_mut().set_status_text(QString::from(msg.as_str())));
                }
            }
        });
    }

    pub fn consult_transfer(self: Pin<&mut Self>) {
        use teams_cli::calling::consult::{Action, Event};
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let mut slot = call_slot().lock().await;
            let (next, action) = slot.consult_state.step(Event::Transfer);
            if action != Action::SendTransfer {
                return;
            }
            let target = next.target().map(|t| t.mri.clone()).unwrap_or_default();
            slot.consult_state = next;
            publish_consult(&qt, &slot);
            let replaces = slot.consult.as_ref().and_then(|c| c.replace_link().map(str::to_string));
            tracing::info!(replaces = replaces.is_some(), "consult transfer");
            let result = match (slot.active.as_ref(), slot.outgoing.as_ref()) {
                (Some(call), _) => match CallAuth::load().await {
                    Ok(auth) => call.transfer(&auth, &target, replaces.as_deref()).await,
                    Err(e) => Err(e),
                },
                (None, Some(call)) => call.transfer(&target, replaces.as_deref()).await,
                _ => Err(anyhow::anyhow!("No call")),
            };
            if let Err(e) = result {
                tracing::warn!("consult transfer: {}", short_error(&e));
                let (next, _) = slot.consult_state.step(Event::Failed);
                slot.consult_state = next;
                publish_consult(&qt, &slot);
                let msg = tr("Transfer failed");
                let _ = qt.queue(move |mut this| this.as_mut().set_status_text(QString::from(msg.as_str())));
            }
        });
    }

    pub fn consult_merge(self: Pin<&mut Self>) {
        use teams_cli::calling::consult::{Action, Event};
        let first_peer = self.rust().call_peer_id.to_string();
        let first_name = self.rust().call_peer.to_string();
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let mut slot = call_slot().lock().await;
            let (next, action) = slot.consult_state.step(Event::Merge);
            if action != Action::SendMerge {
                return;
            }
            let target = next.target().cloned().expect("a consult has a target");
            slot.consult_state = next;
            publish_consult(&qt, &slot);
            let consult_call = slot.consult.take();
            // The held call still holds the first person; take their merge
            // leg from its roster so the service moves them silently (Teams'
            // ReplaceParticipant), else they're invited and ring.
            let first_leg = slot
                .active
                .as_ref()
                .and_then(|c| c.remote_leg(&first_peer))
                .or_else(|| slot.outgoing.as_ref().and_then(|c| c.remote_leg(&first_peer)))
                .or_else(|| slot.roster_legs.get(&first_peer.to_ascii_lowercase()).cloned());
            let result = async {
                let my_oid = teams_cli::config::Config::load().ok().and_then(|c| c.object_id()).context("Not signed in")?;
                // Teams' getCallingConversationWith: the chat of everyone
                // in both calls, which the merged call takes as its group.
                let members = vec![format!("8:orgid:{my_oid}"), first_peer.clone(), target.mri.clone()];
                let client = TeamsClient::new().await?;
                let thread = api::create_group_chat(&client, &members, "").await?;
                let consult = consult_call.as_ref().context("No consult call")?;
                tracing::info!(silent = first_leg.is_some(), "merging the held person in");
                let person = outgoing::MergePerson {
                    id: first_peer.clone(),
                    participant_id: uuid::Uuid::new_v4().to_string(),
                    display_name: Some(first_name.clone()).filter(|n| !n.is_empty()),
                    // Their leg in the held call: the service replaces it
                    // (silent); without it they are invited and ring.
                    replacement: first_leg.clone(),
                };
                consult.merge_in(&thread, &[person]).await?;
                anyhow::Ok(thread)
            }
            .await;
            slot.consult = consult_call;
            match result {
                Ok(thread) => {
                    tracing::info!("calls merged");
                    let (next, _) = slot.consult_state.step(Event::Done);
                    slot.consult_state = next;
                    slot.consult_tag = None;
                    // The consult call goes on as the group call; the held
                    // call is left.
                    let first_active = slot.active.take();
                    let first_outgoing = slot.outgoing.take();
                    // The held call's ends (it ends as we leave it, or as
                    // the service moves its person) aren't the group call's.
                    if first_active.is_some() {
                        slot.superseded_untagged = true;
                    }
                    if let Some(call) = &first_outgoing {
                        slot.left_tags.push(call.call_tag().to_string());
                    }
                    slot.outgoing = slot.consult.take();
                    publish_consult(&qt, &slot);
                    drop(slot);
                    // A silent merge moves the person's leg out of the held
                    // call: leaving it before the service has done so loses
                    // the leg ("Replacement call was not found", measured),
                    // so leave it once the move is done.
                    let silent = first_leg.is_some();
                    runtime().spawn(async move {
                        if silent {
                            tokio::time::sleep(MERGE_LEAVE_DELAY).await;
                        }
                        if let Some(call) = first_outgoing {
                            let _ = call.hang_up().await;
                        }
                        if let Some(call) = first_active
                            && let Ok(auth) = CallAuth::load().await
                        {
                            let _ = auth.hang_up(call).await;
                        }
                        tracing::info!(silent, "left the held call after the merge");
                    });
                    let names = format!("{first_name}, {}", target.name);
                    let _ = qt.queue(move |mut this| {
                        this.as_mut().set_call_held(false);
                        this.as_mut().set_call_peer(QString::from(names.as_str()));
                        this.as_mut().set_call_thread_id(QString::from(thread.as_str()));
                        this.as_mut().set_status_text(QString::from(tr("Calls merged")));
                    });
                }
                Err(e) => {
                    tracing::warn!("merge: {}", short_error(&e));
                    let (next, _) = slot.consult_state.step(Event::Failed);
                    slot.consult_state = next;
                    publish_consult(&qt, &slot);
                    let msg = tr("Couldn't merge calls");
                    let _ = qt.queue(move |mut this| this.as_mut().set_status_text(QString::from(msg.as_str())));
                }
            }
        });
    }

    pub fn consult_end(self: Pin<&mut Self>) {
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let mut slot = call_slot().lock().await;
            if let Some(cancel) = slot.cancel_consult.take() {
                let _ = cancel.send(());
            }
            let call = slot.consult.take();
            consult_ended(&qt, &mut slot).await;
            drop(slot);
            if let Some(call) = call {
                tracing::info!("consult call ended");
                if let Err(e) = call.hang_up().await {
                    tracing::warn!("consult hang up failed: {}", short_error(&e));
                }
            }
        });
    }

    pub fn send_dtmf(self: Pin<&mut Self>, key: &QString) {
        let Some(k) = key.to_string().chars().next() else {
            return;
        };
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let slot = call_slot().lock().await;
            let result = match (slot.active.as_ref(), slot.outgoing.as_ref()) {
                (Some(c), _) => c.send_dtmf(k),
                (None, Some(c)) => c.send_dtmf(k),
                _ => Err(anyhow::anyhow!("No call")),
            };
            drop(slot);
            if let Err(e) = result {
                let _ = qt.queue(move |mut this| {
                    this.as_mut().set_status_text(QString::from(
                        tr("Dial pad: %1").replace("%1", &short_error(&e)).as_str(),
                    ));
                });
            }
        });
    }

    /// Apply roster changes and publish the roster to QML; in a meeting,
    /// ask for the cameras that are on (as Teams' gallery does, in the
    /// roster's order).
    fn apply_roster(mut self: Pin<&mut Self>, delta: Vec<teams_cli::calling::roster::Participant>) {
        // Someone who left ends their RTT line where it stood.
        let left: Vec<String> = delta.iter().filter(|p| !p.active).map(|p| p.id.clone()).collect();
        let mut ended = Vec::new();
        for id in &left {
            ended.extend(self.as_mut().rust_mut().rtt_lines.end_user(id));
        }
        self.as_mut().show_rtt(ended);
        let mut roster = std::mem::take(&mut self.as_mut().rust_mut().roster);
        let gone: Vec<teams_cli::calling::roster::Participant> = delta
            .iter()
            .filter(|p| !p.active)
            .filter_map(|p| roster.iter().find(|r| r.id == p.id).cloned())
            .collect();
        // Who waits in the lobby, from the roster as Teams keeps it: the
        // join response already lists people who waited before you.
        if self.rust().call_meeting {
            let mut lobby = std::mem::take(&mut self.as_mut().rust_mut().lobby_people);
            if teams_cli::calling::roster::apply_lobby(&mut lobby, &delta) {
                tracing::info!(waiting = lobby.len(), "lobby from the roster");
            }
            self.as_mut().rust_mut().lobby_people = lobby;
        }
        teams_cli::calling::roster::apply(&mut roster, delta);

        let json = serde_json::to_string(&roster).unwrap_or_else(|_| "[]".into());
        let me = self.rust().user_mri.to_string().to_ascii_lowercase();
        // Teams Rooms' auto exit: an ad-hoc meeting nobody else is left in.
        // Its getInCallParticipants: everyone connected (people, guests,
        // phone numbers) but calling bots and the room's own endpoints.
        if self.rust().room_mode && self.rust().room_auto_exit && self.rust().call_state.to_string() == "connected" {
            let others = roster.iter().filter(|p| p.id != me && p.active && !p.id.starts_with("28:")).count();
            if teams_cli::calling::room_mode::adhoc_escalated(others) && !self.rust().room_escalated {
                tracing::info!(others, "room mode: the ad-hoc meeting escalated; it waits for its end");
                self.as_mut().rust_mut().room_escalated = true;
            }
            if others > 0 {
                self.as_mut().rust_mut().room_saw_others = true;
            } else if self.rust().room_saw_others && !self.rust().room_escalated {
                tracing::info!("room mode: leaving ad-hoc call because no other participants left in the call");
                self.as_mut().rust_mut().room_saw_others = false;
                self.as_mut().hang_up();
            }
        }
        let off = self.rust().incoming_video_off;
        let widths = self.rust().video_widths.clone();
        let focus = self.rust().video_focus.clone();
        let mut cameras: Vec<(String, i64, u32)> = roster
            .iter()
            .filter(|p| p.id != me && !off)
            .filter_map(|p| {
                let mut w = widths.get(&p.id).copied().unwrap_or(1280.0).round() as u32;
                // Teams' focused tiles (pinned, spotlighted, sign language
                // priority) ask for the main stream at its best.
                if focus.contains(&p.id) {
                    w = w.max(FOCUS_VIDEO_WIDTH);
                }
                p.video_source.map(|s| (p.id.clone(), s, w))
            })
            .collect();
        // They take the video slots first (the rest in roster order).
        cameras.sort_by_key(|c| focus.iter().position(|f| *f == c.0).unwrap_or(usize::MAX));
        // The presenter: whoever else shares their screen.
        let presenter = roster
            .iter()
            .find(|p| p.id != me && p.share_source.is_some())
            .map(|p| (p.id.clone(), p.share_source));
        let share_mri = presenter.as_ref().map(|p| p.0.clone()).unwrap_or_default();
        if self.rust().call_share_mri.to_string() != share_mri {
            self.as_mut()
                .set_call_share_mri(QString::from(share_mri.as_str()));
        }
        let share_source = presenter.and_then(|p| p.1);
        // Give / take control: the presenter we watch; who left.
        let watched = roster.iter().find(|p| p.id != me && p.share_source.is_some()).cloned();
        if let Some(w) = watched.as_ref() {
            let mine = roster.iter().find(|p| p.id == me).map(|p| p.data_sources.clone()).unwrap_or_default();
            if self.rust().presenting_viewing.is_none() {
                tracing::info!(presenter_data = ?w.data_sources, presenter_share_data = ?w.share_data_source, my_data = ?mine, "screen control: data sources");
            }
        }
        self.as_mut().presenting_roster(&gone, watched.as_ref());
        // Presenters in Standout or Reporter send their camera with its
        // background cut out (decoded with Teams' implicit mask).
        let masked: Vec<i64> = roster
            .iter()
            .filter(|p| p.id != me)
            .filter(|p| {
                p.weather_person.as_deref().is_some_and(|w| {
                    serde_json::from_str::<teams_cli::calling::presenter_mode::Published>(w).is_ok_and(|l| l.mode().cuts_background())
                })
            })
            .filter_map(|p| p.video_source)
            .collect();
        // The attendance list: who else is here now.
        if self.rust().call_meeting && !roster.is_empty() {
            let here: Vec<(String, String)> = roster
                .iter()
                .filter(|p| p.id != me && p.active)
                .map(|p| (p.id.clone(), p.name.clone()))
                .collect();
            let (mri, name) = (self.rust().user_mri.to_string(), self.rust().user_name.to_string());
            self.as_mut()
                .rust_mut()
                .attendance
                .update((&mri, &name), &here, chrono::Local::now());
        }
        self.as_mut().rust_mut().roster = roster;
        self.as_mut()
            .set_call_roster_json(QString::from(json.as_str()));
        // Your role may have changed who sees the lobby.
        self.as_mut().publish_lobby();
        // Whiteboard, PowerPoint Live, Excel Live and Annotate others present.
        self.as_mut().content_from_roster();
        // The recording indicator names its starters from the roster.
        if !self.rust().processing.indicator_state().is_empty() {
            self.as_mut().show_recording_indicator();
        }
        if self.rust().call_meeting {
            let qt = self.qt_thread();
            runtime().spawn(async move {
                let sources: Vec<(i64, u32)> = cameras.iter().map(|c| (c.1, c.2)).collect();
                let shown = {
                    let slot = call_slot().lock().await;
                    match (slot.outgoing.as_ref(), slot.active.as_ref()) {
                        (Some(call), _) => {
                            call.show_share(share_source);
                            call.show_videos(&sources)
                        }
                        // Invited into the meeting (a Teams Rooms device
                        // a cast added): the same, over its answer.
                        (None, Some(call)) => {
                            call.show_share(share_source);
                            call.show_videos(&sources)
                        }
                        (None, None) => return,
                    }
                };
                let keys: serde_json::Map<String, serde_json::Value> = cameras
                    .iter()
                    .filter_map(|(mri, src, _)| Some((mri.clone(), shown.get(src)?.clone().into())))
                    .collect();
                let masked_keys: Vec<String> = masked.iter().filter_map(|s| shown.get(s).cloned()).collect();
                teams_cli::calling::frames::set_implicit_masks(&masked_keys);
                let json = serde_json::Value::Object(keys).to_string();
                let _ = qt.queue(move |mut this| {
                    if this.rust().call_video_json.to_string() != json {
                        tracing::info!(videos = %json, "meeting videos");
                        this.as_mut()
                            .set_call_video_json(QString::from(json.as_str()));
                    }
                });
            });
        }
    }

    /// callLobbyJson from the people waiting, for those Teams shows the
    /// lobby to (not an attendee, not anonymous; your role from the roster).
    fn publish_lobby(mut self: Pin<&mut Self>) {
        let me = self.rust().user_mri.to_string().to_ascii_lowercase();
        let role = self.rust().roster.iter().find(|p| p.id == me).map(|p| p.role.clone());
        let shown = teams_cli::calling::roster::sees_lobby(role.as_deref(), me.starts_with("8:teamsvisitor:"));
        let people: Vec<serde_json::Value> = if shown {
            self.rust()
                .lobby_people
                .iter()
                .map(|p| json!({ "id": p.id, "name": p.name, "suspected": p.suspected }))
                .collect()
        } else {
            Vec::new()
        };
        let text = serde_json::to_string(&people).unwrap_or_else(|_| "[]".into());
        if self.rust().call_lobby_json.to_string() != text {
            self.as_mut().set_call_lobby_json(QString::from(text.as_str()));
        }
    }

    /// Show the call as over; the UI fades it out from "ended".
    fn end_call_ui(mut self: Pin<&mut Self>) {
        teams_cli::calling::meeting_media::clear_control_role();
        // A room ended (or was left): the main meeting's kept conversation
        // waits a little for the way back, then is left.
        leave_kept_main_later();
        self.as_mut().rust_mut().presenting_viewing = None;
        self.as_mut().rust_mut().presenting.control = Default::default();
        self.as_mut().content_reset();
        if self.rust().call_test && self.rust().call_test_report.is_empty() {
            let watch = echo_watch().lock().unwrap_or_else(|e| e.into_inner()).take();
            let mut report = watch.map(|w| w.report).unwrap_or_default();
            let (inputs, outputs) = teams_cli::calling::audio::list_devices();
            if inputs.is_empty() {
                report.note(teams_cli::calling::echo_report::Event::NoMics);
            }
            if outputs.is_empty() {
                report.note(teams_cli::calling::echo_report::Event::NoSpeakers);
            }
            let camera = test_camera();
            report.finish(camera.is_some(), self.rust().call_muted, false);
            let (default_mic, default_speaker) = teams_cli::calling::audio::default_devices();
            let settings = load_settings();
            let chosen = |key: &str, default: Option<String>| {
                settings
                    .get(key)
                    .and_then(|v| v.as_str())
                    .filter(|d| !d.is_empty() && *d != "default")
                    .map(str::to_string)
                    .or(default)
            };
            let rows = teams_cli::calling::echo_report::rows(
                &report,
                chosen("micDevice", default_mic).as_deref(),
                chosen("speakerDevice", default_speaker).as_deref(),
                camera.map(|c| c.1).as_deref(),
            );
            tracing::info!(report = %rows, "test call report");
            self.as_mut().set_call_test_report(QString::from(rows.to_string().as_str()));
        }
        self.as_mut().set_call_held(false);
        self.as_mut().set_call_held_by_peer(false);
        self.as_mut().set_call_e2ee(false);
        self.as_mut().set_call_e2ee_numbers(QString::default());
        self.as_mut().set_call_can_park(false);
        self.as_mut().set_call_park_code(QString::default());
        self.as_mut().set_call_continues(false);
        self.as_mut().set_call_voicemail(false);
        self.as_mut().set_call_can_dtmf(false);
        self.as_mut().set_call_hand_raised(false);
        if !self.rust().call_state.is_empty() {
            self.as_mut().set_call_state(QString::from("ended"));
        }
        self.as_mut().set_call_camera_on(false);
        self.as_mut().set_call_network_strength(QString::from("Good"));
        self.as_mut().set_call_can_video(false);
        self.as_mut().set_call_can_share(false);
        self.as_mut().set_call_sharing(false);
    }

    /// Poll the presence of 1:1 chat partners every minute (Teams shows a
    /// badge on each avatar).
    fn start_presence(self: Pin<&mut Self>) {
        static STARTED: AtomicBool = AtomicBool::new(false);
        if STARTED.swap(true, Ordering::SeqCst) {
            return;
        }
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let http = reqwest::Client::new();
            loop {
                let (tx, rx) = tokio::sync::oneshot::channel::<Vec<String>>();
                let _ = qt.queue(move |this| {
                    let mut mris: Vec<String> = this
                        .rust()
                        .chats
                        .iter()
                        .filter_map(|c| c["peerMri"].as_str().map(str::to_string))
                        .collect();
                    // Yours too (your status message).
                    if let Some(me) = this.rust().my_mri.clone()
                        && !mris.iter().any(|m| m.eq_ignore_ascii_case(&me))
                    {
                        mris.push(me);
                    }
                    let _ = tx.send(mris);
                });
                let mris = rx.await.unwrap_or_default();
                match teams_cli::api::presence::get_presences(&http, &mris).await {
                    Ok(list) => {
                        let _ = qt.queue(move |mut this| {
                            let me = this.rust().my_mri.clone().unwrap_or_default();
                            for p in list {
                                if p.mri.eq_ignore_ascii_case(&me) {
                                    let note = json!({ "text": p.note_text, "html": p.note_html, "pinned": p.note_pinned, "expiry": p.note_expiry }).to_string();
                                    if this.rust().my_note_json.to_string() != note {
                                        this.as_mut().set_my_note_json(QString::from(note.as_str()));
                                    }
                                    if this.rust().my_status_ends.to_string() != p.forced_until {
                                        this.as_mut().set_my_status_ends(QString::from(p.forced_until.as_str()));
                                    }
                                    if this.rust().my_work_location.to_string() != p.work_location {
                                        this.as_mut().set_my_work_location(QString::from(p.work_location.as_str()));
                                    }
                                }
                                let note = json!({ "text": p.note_text, "html": p.note_html, "pinned": p.note_pinned, "ooo": p.out_of_office });
                                this.as_mut().rust_mut().peer_notes.insert(p.mri.clone(), note);
                                this.as_mut()
                                    .rust_mut()
                                    .presence
                                    .insert(p.mri, p.availability);
                            }
                            this.as_mut().publish_chats();
                        });
                    }
                    Err(e) => tracing::warn!("presence lookup failed: {}", short_error(&e)),
                }
                tokio::time::sleep(std::time::Duration::from_secs(60)).await;
            }
        });
    }

    /// Teams' chat bubble: someone else's message in the chat of the call
    /// we're in, unless bubbles are off for this call.
    fn maybe_chat_bubble(self: Pin<&mut Self>, m: &teams_cli::event_hub::PushedMessage) {
        let in_call = self.rust().call_state.to_string() == "connected";
        let thread = self.rust().call_thread_id.to_string();
        if !in_call || thread.is_empty() || m.conversation_id != thread || self.rust().call_chat_bubbles_suppressed {
            return;
        }
        let mine = self.rust().my_mri.as_deref().is_some_and(|me| me.eq_ignore_ascii_case(&m.sender_mri))
            || (!m.sender_name.is_empty() && m.sender_name == self.rust().user_name.to_string());
        if mine || m.text.trim().is_empty() {
            return;
        }
        // Teams previews the first 200 characters.
        let text: String = m.text.chars().take(200).collect();
        self.chat_bubble(
            QString::from(m.sender_mri.as_str()),
            QString::from(m.sender_name.as_str()),
            QString::from(text.as_str()),
        );
    }

    /// Show a desktop notification for someone else's message, unless its
    /// chat is open in the focused window.
    fn maybe_notify(
        mut self: Pin<&mut Self>,
        m: teams_cli::event_hub::PushedMessage,
        qt: cxx_qt::CxxQtThread<qobject::Backend>,
    ) {
        let own = self.rust().user_name.to_string();
        let mine = (!m.sender_name.is_empty() && m.sender_name == own)
            || self
                .rust()
                .my_mri
                .as_deref()
                .is_some_and(|me| me.eq_ignore_ascii_case(&m.sender_mri));
        let open = self.rust().window_active
            && m.conversation_id == self.rust().current_chat_id.to_string();
        // Settings ▸ Notifications and activity, as Teams applies it.
        let prefs = notify_prefs(&self.rust().settings_json.to_string(), &load_settings());
        // Muted for this call (More ▸ Settings ▸ Mute notifications), or
        // notifications off during calls and meetings.
        let in_call = ["connected", "connecting", "calling"].contains(&self.rust().call_state.to_string().as_str());
        let banners_on = (!prefs.mute_all || (m.urgent && prefs.allow_urgent_when_muted))
            && !(in_call && (self.rust().call_notifications_muted || !prefs.during_calls));
        let mentioned = self
            .rust()
            .my_mri
            .as_deref()
            .is_some_and(|me| m.mentions.iter().any(|x| x.eq_ignore_ascii_case(me)));
        let channel = m.conversation_id.ends_with("@thread.tacv2");
        let muted = chat_muted(&self.rust().chats, &m.conversation_id);
        // A personal @mention banners unless that's off; a chat message
        // banners when chat banners are on; channel posts and muted chats
        // only for mentions.
        let mention_banner = mentioned && prefs.personal_mention_banners;
        if !should_notify(
            mine,
            open,
            m.text.is_empty(),
            banners_on,
            !prefs.chat_banners,
            channel || muted,
            mention_banner,
        ) {
            return;
        }
        // Your presence decides, as in Teams.
        let availability = self
            .rust()
            .my_mri
            .as_deref()
            .and_then(|me| self.rust().presence.get(me).cloned())
            .unwrap_or_default();
        let presenting = teams_cli::api::presence::changes().borrow().call
            == teams_cli::api::presence::CallState::Presenting;
        let decision = toast_decision(&availability, presenting, m.urgent);
        if decision == Toast::Drop {
            return;
        }
        let chat_name = if channel {
            self.channel_label(&m.conversation_id)
        } else {
            self.rust()
                .chats
                .iter()
                .find(|c| c["id"].as_str() == Some(m.conversation_id.as_str()))
                .and_then(|c| c["name"].as_str().map(str::to_string))
                .unwrap_or_default()
        };
        // Teams' wording (react-web-client 1920 `ir`): a 1:1 chat's
        // banner is the sender (or "<sender> sent an urgent message") and
        // the message; a group chat's is its name and "<sender>: <text>";
        // an @mention is "<sender> @mentioned you" (in a thread, for a
        // channel reply) over where it was said. Previews off: "Message
        // preview hidden".
        let one_on_one = m.conversation_id.ends_with("@unq.gbl.spaces");
        let sender = if m.sender_name.is_empty() { tr("Unknown User") } else { m.sender_name.clone() };
        let preview: String = if prefs.previews {
            m.text.chars().take(NOTIFICATION_BODY_CHARS).collect()
        } else {
            tr("Message preview hidden")
        };
        let mention = mentioned && prefs.personal_mention_banners;
        let (title, subtitle, text) = if mention {
            let title = if m.root_id.is_some() {
                tr("%1 @mentioned you in a thread").replace("%1", &sender)
            } else {
                tr("%1 @mentioned you").replace("%1", &sender)
            };
            let place = if chat_name.is_empty() { tr("Chat with %1").replace("%1", &sender) } else { chat_name.clone() };
            (title, place, preview.clone())
        } else if one_on_one {
            let title = if m.urgent { tr("%1 sent an urgent message").replace("%1", &sender) } else { sender.clone() };
            (title, String::new(), preview.clone())
        } else {
            let title = if chat_name.is_empty() { tr("Unknown") } else { chat_name.clone() };
            (title, String::new(), tr("%1: %2").replace("%1", &sender).replace("%2", &preview))
        };
        let (title, subtitle, text) = if decision == Toast::Redacted {
            (tr("You have a new notification"), String::new(), String::new())
        } else {
            (title, subtitle, text)
        };
        let chat_id = m.conversation_id.clone();
        let busy = matches!(availability.as_str(), "Busy" | "DoNotDisturb" | "InACall" | "InAMeeting") || in_call;
        let silent = !prefs.sound || (busy && !prefs.sound_when_busy);
        let timeout = prefs.seconds * 1000;
        if prefs.flash {
            self.as_mut().flash_requested();
        }
        if banners_available() {
            // Teams offers a quick reply on chat messages it previews
            // (not on @mentions, nor in channels).
            let quick_reply = !mention && !channel && prefs.previews && decision != Toast::Redacted;
            let banner = serde_json::json!({
                "id": format!("msg:{}:{}", m.conversation_id, m.message_id),
                "kind": "standard",
                "title": title, "subtitle": subtitle, "text": text,
                "chatId": chat_id, "chatName": chat_name,
                "messageId": m.message_id,
                "senderMri": m.sender_mri, "senderName": m.sender_name,
                "urgent": m.urgent,
                "quickReply": quick_reply,
                "seconds": prefs.seconds,
                "silent": silent,
                "sound": if m.urgent && prefs.urgent_sounds { &prefs.urgent_sound_file } else { &prefs.sound_file },
            });
            // A group chat's banner names the sender as Teams does: "OST:
            // hello" (their short name, which needs their profile once).
            let group = !mention && !one_on_one && decision != Toast::Redacted;
            if group && !m.sender_mri.is_empty() {
                let (mri, display, preview) = (m.sender_mri.clone(), sender.clone(), preview.clone());
                let qt = self.qt_thread();
                runtime().spawn(async move {
                    let short = sender_short_name(&mri, &display).await;
                    let mut banner = banner;
                    banner["text"] = serde_json::Value::String(tr("%1: %2").replace("%1", &short).replace("%2", &preview));
                    let _ = qt.queue(move |mut this| this.as_mut().banner_requested(QString::from(banner.to_string().as_str())));
                });
                return;
            }
            self.as_mut().banner_requested(QString::from(banner.to_string().as_str()));
            return;
        }
        let body = if subtitle.is_empty() { text } else { format!("{subtitle}\n{text}") };
        std::thread::spawn(move || {
            let shown = notify_rust::Notification::new()
                .appname("OST")
                .summary(&title)
                .body(&body)
                .icon("ost-desktop")
                .action("default", &tr("Open"))
                .hint(notify_rust::Hint::Category("im.received".into()))
                .hint(notify_rust::Hint::SuppressSound(silent))
                .timeout(notify_rust::Timeout::Milliseconds(timeout))
                .show();
            match shown {
                Ok(handle) => handle.wait_for_action(|action| {
                    if action == "default" {
                        let _ = qt.queue(move |mut this| {
                            // Settings ▸ General ▸ Opening content in OST
                            // windows: the chat in a window of its own, or in
                            // the main window.
                            if load_settings().get("openContentIn").and_then(|v| v.as_str()) == Some("popout") {
                                this.as_mut().open_chat_window_requested(QString::from(chat_id.as_str()), QString::from(chat_name.as_str()));
                                return;
                            }
                            this.as_mut().select_chat(
                                &QString::from(chat_id.as_str()),
                                &QString::from(chat_name.as_str()),
                            );
                            this.as_mut().activate_requested();
                        });
                    }
                }),
                Err(e) => tracing::warn!("notification failed: {e}"),
            }
        });
    }

    /// Teams' toast for Meet now started in a chat (527114 `uMe`): the chat's
    /// name (or "(No title)"), "{name} started a meeting", Join and Message.
    /// As Teams does, once per call, not for muted chats nor when we're
    /// already in that chat's call, and by the same banner and presence
    /// rules as messages. The
    /// chat list reloads too: its liveness entry has changed.
    fn notify_meeting_start(
        mut self: Pin<&mut Self>,
        start: teams_cli::calling::incoming::MeetingStart,
        qt: cxx_qt::CxxQtThread<qobject::Backend>,
    ) {
        static SHOWN: OnceLock<std::sync::Mutex<std::collections::HashSet<String>>> =
            OnceLock::new();
        // A scheduled meeting's notification names only who started it (its
        // MRI): Teams' "{{meetingCaller}} started the meeting" needs the name.
        let mut start = start;
        if start.initiator_name.is_empty() && !start.initiator.is_empty() {
            let known: serde_json::Map<String, serde_json::Value> =
                serde_json::from_str(&self.rust().people_names_json.to_string()).unwrap_or_default();
            if let Some(n) = known.get(&start.initiator).and_then(|n| n.as_str()).filter(|n| !n.is_empty()) {
                start.initiator_name = n.to_string();
            } else {
                let qt2 = qt.clone();
                runtime().spawn(async move {
                    let name = async {
                        let client = TeamsClient::new().await?;
                        api::directory::short_profiles(&client, std::slice::from_ref(&start.initiator)).await
                    }
                    .await
                    .ok()
                    .and_then(|found| found.into_iter().next().map(|(_, n)| n))
                    .filter(|n| !n.is_empty())
                    .unwrap_or_else(|| tr("Someone"));
                    start.initiator_name = name;
                    let qt3 = qt2.clone();
                    let _ = qt2.queue(move |mut this| this.as_mut().notify_meeting_start(start, qt3));
                });
                return;
            }
        }
        // Teams looks the scheduled meeting up in your calendar (its
        // calendar-service check). One that isn't in the range loaded here
        // (an invitation that came after it loaded, or another week shown)
        // is looked up around now first; a failed lookup counts as found,
        // as in Teams.
        static LOOKED_UP: OnceLock<std::sync::Mutex<HashMap<String, Option<serde_json::Value>>>> = OnceLock::new();
        let thread_enc = start.thread_id.replace(':', "%3a").replace('@', "%40").to_lowercase();
        let in_calendar = |e: &serde_json::Value| e["join_url"].as_str().is_some_and(|u| u.to_lowercase().contains(&thread_enc));
        let mut looked_up: Option<Option<serde_json::Value>> = None;
        if start.scheduled {
            let calendar: Vec<serde_json::Value> = serde_json::from_str(&self.rust().calendar_json.to_string()).unwrap_or_default();
            if !calendar.iter().any(in_calendar) {
                let known = LOOKED_UP.get_or_init(Default::default).lock().ok().and_then(|mut m| m.remove(&start.call_id));
                match known {
                    Some(found) => looked_up = Some(found),
                    None => {
                        let qt2 = qt.clone();
                        let thread_enc = thread_enc.clone();
                        runtime().spawn(async move {
                            let now = chrono::Utc::now();
                            let fmt = |t: chrono::DateTime<chrono::Utc>| t.format("%Y-%m-%dT%H:%M:%SZ").to_string();
                            let found = async {
                                let client = TeamsClient::new().await?;
                                api::calendar::calendar_view(&client, &fmt(now - chrono::Duration::days(1)), &fmt(now + chrono::Duration::days(1))).await
                            }
                            .await;
                            let entry = match found {
                                Ok(events) => events
                                    .iter()
                                    .map(|e| serde_json::to_value(e).unwrap_or_default())
                                    .find(|e| e["join_url"].as_str().is_some_and(|u| u.to_lowercase().contains(&thread_enc)))
                                    .unwrap_or(serde_json::Value::Null),
                                Err(e) => {
                                    tracing::warn!("meeting start: calendar lookup failed, assuming it's there: {}", short_error(&e));
                                    serde_json::json!({})
                                }
                            };
                            let found = entry.get("id").is_some();
                            tracing::info!(found = !entry.is_null(), "meeting start: looked the meeting up in the calendar");
                            if let Ok(mut m) = LOOKED_UP.get_or_init(Default::default).lock() {
                                m.insert(start.call_id.clone(), Some(entry));
                            }
                            let qt3 = qt2.clone();
                            let _ = qt2.queue(move |mut this| {
                                // The calendar shown hasn't got it yet: reload it.
                                if found {
                                    this.as_mut().refresh_calendar();
                                }
                                this.as_mut().notify_meeting_start(start, qt3)
                            });
                        });
                        return;
                    }
                }
            }
        }
        self.as_mut().reload_chats();
        let first = SHOWN
            .get_or_init(Default::default)
            .lock()
            .map(|mut s| s.insert(start.call_id.clone()))
            .unwrap_or(false);
        let mine = self
            .rust()
            .my_mri
            .as_deref()
            .is_some_and(|me| me.eq_ignore_ascii_case(&start.initiator));
        let in_it = !self.rust().call_state.is_empty()
            && self.rust().call_thread_id.to_string() == start.thread_id;
        // Settings ▸ Notifications ▸ Meet now start notifications (off by
        // default, as in Teams), unless everything is muted. A scheduled
        // meeting: Meeting start notifications (on by default).
        let prefs = notify_prefs(&self.rust().settings_json.to_string(), &load_settings());
        let banners_on = (if start.scheduled { prefs.meeting_start } else { prefs.meet_now }) && !prefs.mute_all;
        if start.scheduled {
            // Teams' live-meeting checks: the meeting is in your calendar
            // (by its thread), from 15 minutes before its start to 5 after
            // its end, and you didn't decline it.
            let calendar: Vec<serde_json::Value> = serde_json::from_str(&self.rust().calendar_json.to_string()).unwrap_or_default();
            let now = chrono::Utc::now();
            let fetched = looked_up.clone().flatten();
            // Not found by the lookup (null): not in your calendar.
            let lookup_missed = fetched.as_ref().is_some_and(|v| v.is_null());
            let event = calendar.iter().find(|e| in_calendar(e)).or(fetched.as_ref().filter(|v| v.is_object()));
            let at = |e: &serde_json::Value, k: &str| e[k].as_str().and_then(|x| chrono::DateTime::parse_from_rfc3339(x).ok());
            let ok = match event {
                Some(e) => {
                    let declined = e["response"].as_str() == Some("declined");
                    let window = at(e, "start_utc").zip(at(e, "end_utc")).is_none_or(|(s, en)| {
                        now >= s - chrono::Duration::minutes(15) && now <= en + chrono::Duration::minutes(5)
                    });
                    !declined && window
                }
                None => !lookup_missed,
            };
            let declined = start.rsvp.to_ascii_lowercase().contains("decline");
            tracing::info!(thread = %start.thread_id, ok, declined, rsvp = %start.rsvp, "scheduled meeting started");
            if !ok || declined {
                return;
            }
            // The live meeting join bar (Show meeting join bar).
            if prefs.join_bar && !in_it && !mine {
                let mut live: Vec<serde_json::Value> = serde_json::from_str(&self.rust().live_meetings_json.to_string()).unwrap_or_default();
                live.retain(|m| m["threadId"].as_str() != Some(start.thread_id.as_str()));
                live.push(serde_json::json!({
                    "threadId": start.thread_id, "callId": start.call_id,
                    "subject": if start.subject.is_empty() { event.and_then(|e| e["subject"].as_str()).map(str::to_string).unwrap_or_else(|| tr("(No title)")) } else { start.subject.clone() },
                    "joinUrl": if start.join_url.is_empty() { event.and_then(|e| e["join_url"].as_str()).unwrap_or_default() } else { &start.join_url },
                    "start": event.and_then(|e| e["start_utc"].as_str()).unwrap_or_default(),
                    "end": event.and_then(|e| e["end_utc"].as_str()).unwrap_or_default(),
                    // For Teams' "Live meetings" dialog: the card's location,
                    // "{organizer} invited you", your answer (its bar), how
                    // long the call has run and who started it.
                    "location": event.and_then(|e| e["location"].as_str()).unwrap_or_default(),
                    "organizer": event.and_then(|e| e["organizer"].as_str()).unwrap_or_default(),
                    "isOrganizer": event.and_then(|e| e["is_organizer"].as_bool()).unwrap_or(false),
                    "response": event.and_then(|e| e["response"].as_str()).unwrap_or_default(),
                    "showAs": event.and_then(|e| e["show_as"].as_str()).unwrap_or_default(),
                    "startedAt": now.to_rfc3339(),
                    "initiator": start.initiator, "initiatorName": start.initiator_name,
                }));
                self.as_mut().set_live_meetings_json(QString::from(serde_json::Value::Array(live).to_string().as_str()));
            }
        }
        let muted = chat_muted(&self.rust().chats, &start.thread_id);
        if !first || mine || in_it || !banners_on || muted {
            return;
        }
        let availability = self
            .rust()
            .my_mri
            .as_deref()
            .and_then(|me| self.rust().presence.get(me).cloned())
            .unwrap_or_default();
        let presenting = teams_cli::api::presence::changes().borrow().call
            == teams_cli::api::presence::CallState::Presenting;
        let decision = toast_decision(&availability, presenting, false);
        if decision == Toast::Drop {
            return;
        }
        let chat_name = self
            .rust()
            .chats
            .iter()
            .find(|c| c["id"].as_str() == Some(start.thread_id.as_str()))
            .and_then(|c| c["name"].as_str().map(str::to_string))
            .filter(|n| !n.is_empty())
            .unwrap_or_else(|| tr("(No title)"));
        let who = if start.initiator_name.is_empty() {
            tr("Someone")
        } else {
            start.initiator_name.clone()
        };
        // A scheduled meeting is named by its subject; Teams' string is
        // "{{meetingCaller}} started the meeting", its actions Join and Chat.
        let chat_name = if start.scheduled && !start.subject.is_empty() { start.subject.clone() } else { chat_name };
        let (title, body) = if decision == Toast::Redacted {
            (tr("You have a new notification"), String::new())
        } else if start.scheduled {
            (chat_name.clone(), tr("%1 started the meeting").replace("%1", &who))
        } else {
            (chat_name.clone(), tr("%1 started a meeting").replace("%1", &who))
        };
        let second = if start.scheduled { ("chat", tr("Chat")) } else { ("message", tr("Message")) };
        let chat_id = start.thread_id.clone();
        let (scheduled, join_url) = (start.scheduled, start.join_url.clone());
        if banners_available() {
            // Teams' meeting-started banner (notifications-app `st`): on
            // screen 20 seconds, with Join and Message (Chat for a
            // scheduled meeting).
            let banner = serde_json::json!({
                "id": format!("msn:{}", start.call_id),
                "kind": "msn",
                "title": title, "text": body,
                "chatId": chat_id, "chatName": chat_name,
                "joinUrl": start.join_url,
                "senderMri": start.initiator, "senderName": who,
                "seconds": 20,
                // Teams' meeting-started sound (its MeetingStarted toast sound).
                "silent": !prefs.sound || !prefs.call_sounds,
                "sound": "teams_meet_up_reminder",
                "actions": [{ "id": "join", "label": tr("Join") }, { "id": second.0, "label": second.1 }],
            });
            self.as_mut().banner_requested(QString::from(banner.to_string().as_str()));
            return;
        }
        std::thread::spawn(move || {
            let shown = notify_rust::Notification::new()
                .appname("OST")
                .summary(&title)
                .body(&body)
                .icon("ost-desktop")
                .action("join", &tr("Join"))
                .action(second.0, &second.1)
                .action("default", &tr("Open"))
                .hint(notify_rust::Hint::Category("call".into()))
                .show();
            match shown {
                Ok(handle) => handle.wait_for_action(|action| {
                    let join = action == "join";
                    if join || action == "message" || action == "chat" || action == "default" {
                        let _ = qt.queue(move |mut this| {
                            this.as_mut().select_chat(
                                &QString::from(chat_id.as_str()),
                                &QString::from(chat_name.as_str()),
                            );
                            this.as_mut().activate_requested();
                            if join {
                                if scheduled && !join_url.is_empty() { this.as_mut().prejoin_requested(QString::from(join_url.as_str()), QString::from(chat_name.as_str())) } else { this.as_mut().join_group_call(); }
                            }
                        });
                    }
                }),
                Err(e) => tracing::warn!("notification failed: {e}"),
            }
        });
    }

    /// "Team > Channel" for a channel id, from the teams list.
    fn channel_label(&self, id: &str) -> String {
        let teams: serde_json::Value =
            serde_json::from_str(&self.rust().teams_json.to_string()).unwrap_or_default();
        teams
            .as_array()
            .into_iter()
            .flatten()
            .find_map(|t| {
                let ch = t["channels"].as_array()?.iter().find(|c| c["id"] == id)?;
                Some(format!(
                    "{} > {}",
                    t["name"].as_str().unwrap_or_default(),
                    ch["name"].as_str().unwrap_or_default()
                ))
            })
            .unwrap_or_default()
    }

    fn on_typing(mut self: Pin<&mut Self>, t: teams_cli::event_hub::Typing) {
        tracing::info!(
            stopped = t.stopped,
            named = !t.sender_name.is_empty(),
            "typing event"
        );
        let chat = self.rust().current_chat_id.to_string();
        let mine = self
            .rust()
            .my_mri
            .as_deref()
            .is_some_and(|me| me.eq_ignore_ascii_case(&t.sender_mri))
            || (t.sender_mri.is_empty() && t.sender_name == self.rust().user_name.to_string());
        // Teams shows no typing indicator in channels, nor in chats above
        // its roster limit.
        if t.conversation_id != chat
            || mine
            || chat.ends_with("@thread.tacv2")
            || api::messages::roster_size(&chat).is_some_and(|n| n > api::messages::MAX_ROSTER)
        {
            return;
        }
        let key = if t.sender_mri.is_empty() {
            t.sender_name.clone()
        } else {
            t.sender_mri.to_ascii_lowercase()
        };
        // The name: the event's, else the person's (Teams resolves it from
        // the MRI); looked up first if not yet known.
        let name = if !t.sender_name.is_empty() {
            Some(t.sender_name.clone())
        } else {
            api::messages::cached_name(&t.sender_mri)
        };
        let Some(name) = name else {
            if t.stopped || t.sender_mri.is_empty() {
                return;
            }
            let qt = self.qt_thread();
            let one_on_one = chat.ends_with("@unq.gbl.spaces");
            let fallback = self.rust().current_chat_name.to_string();
            runtime().spawn(async move {
                let found = match TeamsClient::new().await {
                    Ok(client) => api::messages::person_name(&client, &t.sender_mri).await,
                    Err(_) => None,
                };
                // A 1:1 chat's other member is the one the chat is named after.
                let Some(name) = found.or_else(|| one_on_one.then_some(fallback)) else {
                    return;
                };
                let _ = qt.queue(move |mut this| {
                    this.as_mut().on_typing(teams_cli::event_hub::Typing {
                        sender_name: name,
                        ..t
                    })
                });
            });
            return;
        };
        let now = std::time::Instant::now();
        let typers = &mut self.as_mut().rust_mut().typers;
        typers.retain(|x| x.key != key && x.until > now);
        if !t.stopped {
            typers.push(Typer {
                key,
                name,
                until: now + std::time::Duration::from_secs(TYPING_TTL_SECS),
            });
        }
        self.as_mut().refresh_typing();
    }

    /// A message from someone typing ends their typing (Teams: any other
    /// message from that user removes them); the others stay.
    fn typer_posted(mut self: Pin<&mut Self>, m: &teams_cli::event_hub::PushedMessage) {
        if m.conversation_id != self.rust().current_chat_id.to_string() {
            return;
        }
        let mri = m.sender_mri.to_ascii_lowercase();
        let before = self.rust().typers.len();
        self.as_mut()
            .rust_mut()
            .typers
            .retain(|x| x.key != mri && x.key != m.sender_name);
        if self.rust().typers.len() != before {
            self.as_mut().refresh_typing();
        }
    }

    /// Show who is typing, as Teams words it; when the last typer leaves,
    /// the line stays 3 s more. Expired typers drop off on their own.
    fn refresh_typing(mut self: Pin<&mut Self>) {
        let now = std::time::Instant::now();
        self.as_mut().rust_mut().typers.retain(|x| x.until > now);
        let names: Vec<String> = self.rust().typers.iter().map(|x| x.name.clone()).collect();
        let generation = self.rust().typing_generation + 1;
        self.as_mut().rust_mut().typing_generation = generation;
        let qt = self.qt_thread();
        if names.is_empty() {
            runtime().spawn(async move {
                tokio::time::sleep(std::time::Duration::from_millis(3000)).await;
                let _ = qt.queue(move |mut this| {
                    if this.rust().typing_generation == generation {
                        this.as_mut().set_typing_text(QString::default());
                        this.as_mut().set_typing_avatar(QString::default());
                        this.as_mut().set_typing_avatar_id(QString::default());
                    }
                });
            });
            return;
        }
        let text = typing_text(&names);
        if let Some(latest) = self.rust().typers.last().cloned() {
            let id = latest.key.strip_prefix("8:orgid:").unwrap_or_default();
            self.as_mut().set_typing_avatar_id(QString::from(id));
            self.as_mut()
                .set_typing_avatar(QString::from(latest.name.as_str()));
        }
        self.as_mut().set_typing_text(QString::from(text.as_str()));
        // Wake when the next typer expires.
        let next = self
            .rust()
            .typers
            .iter()
            .map(|x| x.until)
            .min()
            .unwrap_or(now);
        runtime().spawn(async move {
            tokio::time::sleep(next.saturating_duration_since(std::time::Instant::now())).await;
            let _ = qt.queue(move |mut this| {
                if this.rust().typing_generation == generation {
                    this.as_mut().refresh_typing();
                }
            });
        });
    }

    /// Reload the calendar range last shown (after scheduling something).
    fn refresh_calendar(mut self: Pin<&mut Self>) {
        if let Some((a, b)) = self.rust().calendar_range.clone() {
            self.as_mut()
                .load_calendar(&QString::from(a.as_str()), &QString::from(b.as_str()));
        }
    }

    pub fn load_calendar(mut self: Pin<&mut Self>, start_utc: &QString, end_utc: &QString) {
        let (start, end) = (start_utc.to_string(), end_utc.to_string());
        self.as_mut().rust_mut().calendar_range = Some((start.clone(), end.clone()));
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let result = async {
                let client = TeamsClient::new().await?;
                api::calendar::calendar_view(&client, &start, &end).await
            }
            .await;
            match result {
                Ok(events) => {
                    tracing::info!(events = events.len(), %start, %end, "calendar loaded");
                    let text = serde_json::to_string(&events).unwrap_or_else(|_| "[]".into());
                    let range = (start.clone(), end.clone());
                    let _ = qt.queue(move |mut this| {
                        // A range shown since (switching views) wins over this one.
                        if this.rust().calendar_range.as_ref() != Some(&range) {
                            return;
                        }
                        this.as_mut()
                            .set_calendar_json(QString::from(text.as_str()))
                    });
                }
                Err(e) => tracing::warn!("calendar failed: {}", short_error(&e)),
            }
        });
    }

    pub fn search_people(self: Pin<&mut Self>, query: &QString) {
        self.search_people_impl(query, false)
    }

    pub fn search_people_with_me(self: Pin<&mut Self>, query: &QString) {
        self.search_people_impl(query, true)
    }

    fn search_people_impl(mut self: Pin<&mut Self>, query: &QString, include_me: bool) {
        let q = query.to_string();
        let generation = self.rust().people_query_generation + 1;
        self.as_mut().rust_mut().people_query_generation = generation;
        if q.trim().len() < 2 {
            self.as_mut().set_people_json(QString::from("[]"));
            return;
        }
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let result = async {
                let client = TeamsClient::new().await?;
                api::directory::search_directory(&client, &q, include_me).await
            }
            .await;
            let _ = qt.queue(move |mut this| {
                // A newer query has been typed since.
                if this.rust().people_query_generation != generation {
                    return;
                }
                match result {
                    Ok(people) => {
                        let text = serde_json::to_string(&people).unwrap_or_else(|_| "[]".into());
                        this.as_mut().set_people_json(QString::from(text.as_str()));
                    }
                    Err(e) => tracing::warn!("people search failed: {}", short_error(&e)),
                }
            });
        });
    }

    pub fn new_chat_people(mut self: Pin<&mut Self>, query: &QString) {
        let q = query.to_string().trim().to_string();
        let generation = self.rust().new_chat_people_generation + 1;
        self.as_mut().rust_mut().new_chat_people_generation = generation;
        let (my_mail, my_name) = (self.rust().user_mail.to_string(), self.rust().user_name.to_string());
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let result = async {
                let me = TeamsClient::new().await.ok().and_then(|c| c.object_id()).unwrap_or_default();
                let items = if q.is_empty() {
                    api::search::zero_state_people(&me, &my_mail, &my_name).await?
                } else {
                    api::search::people_only(api::search::recipients(&q, &me).await?, 20)
                };
                anyhow::Ok(items)
            }
            .await;
            let _ = qt.queue(move |mut this| {
                if this.rust().new_chat_people_generation != generation {
                    return;
                }
                match result {
                    Ok(items) => {
                        let items: Vec<serde_json::Value> = items
                            .into_iter()
                            .map(|p| json!({ "id": p["oid"], "name": p["name"], "sub": p["sub"], "guest": p["guest"], "upn": p["upn"] }))
                            .collect();
                        let v = json!({ "query": q, "items": items });
                        this.as_mut().set_new_chat_people_json(QString::from(v.to_string().as_str()));
                    }
                    Err(e) => tracing::warn!("new chat suggestions failed: {}", short_error(&e)),
                }
            });
        });
    }

    pub fn open_chat_with(self: Pin<&mut Self>, oid: &QString, name: &QString) {
        let Some(me) = teams_cli::config::Config::load()
            .ok()
            .and_then(|c| c.object_id())
        else {
            return;
        };
        let id = api::directory::one_on_one_chat_id(&me, &oid.to_string());
        self.select_chat(&QString::from(id.as_str()), name);
    }

    pub fn load_calls(self: Pin<&mut Self>) {
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let result = async {
                let client = TeamsClient::new().await?;
                let mut calls = api::call_history(&client, CALL_HISTORY_LIMIT).await?;
                // Calls OST placed carry no display name for the other
                // side; look those people up once each.
                let mut names: HashMap<String, String> = HashMap::new();
                for c in calls.iter().filter(|c| !c.peer_name.is_empty()) {
                    names
                        .entry(c.peer_mri.clone())
                        .or_insert_with(|| c.peer_name.clone());
                }
                for c in calls.iter_mut().filter(|c| c.peer_name.is_empty()) {
                    if let Some(n) = names.get(&c.peer_mri) {
                        c.peer_name = n.clone();
                        continue;
                    }
                    let Some(oid) = c
                        .peer_mri
                        .strip_prefix("8:orgid:")
                        .filter(|o| o.chars().all(|ch| ch.is_ascii_hexdigit() || ch == '-'))
                    else {
                        continue;
                    };
                    if let Ok(r) = client
                        .graph_get(&format!("/users/{oid}?$select=displayName"))
                        .await
                    {
                        let v: serde_json::Value = r.json().await.unwrap_or_default();
                        if let Some(n) = v["displayName"].as_str() {
                            names.insert(c.peer_mri.clone(), n.to_string());
                            c.peer_name = n.to_string();
                        }
                    }
                }
                anyhow::Ok(calls)
            }
            .await;
            match result {
                Ok(calls) => {
                    let text = serde_json::to_string(&calls).unwrap_or_else(|_| "[]".into());
                    let _ = qt.queue(move |mut this| {
                        this.as_mut().set_calls_json(QString::from(text.as_str()))
                    });
                }
                Err(e) => tracing::warn!("call history failed: {}", short_error(&e)),
            }
        });
    }

    pub fn edit_message(self: Pin<&mut Self>, message_id: &QString, text: &QString) {
        let (id, text) = (message_id.to_string(), text.to_string());
        if text.trim().is_empty() {
            return;
        }
        let at = id.clone();
        self.message_action(&at, move |client, chat| {
            Box::pin(async move { api::messages::edit_message(&client, &chat, &id, &text).await })
        });
    }

    pub fn set_thread_read(self: Pin<&mut Self>, root_id: &QString, change: &QString, newest_reply: &QString) {
        use api::msgactions::HorizonChange;
        let id = root_id.to_string();
        let newest = newest_reply.to_string().parse::<i64>().unwrap_or(0);
        let change = match (change.to_string().as_str(), newest) {
            ("clear", _) => HorizonChange::ClearBookmark,
            ("read", n) if n > 0 => HorizonChange::ReadTo(n),
            ("unread", n) if n > 0 => HorizonChange::UnreadFrom(n),
            _ => return,
        };
        let at = id.clone();
        self.message_action(&at, move |client, chat| {
            Box::pin(async move { api::msgactions::set_thread_horizon(&client, &chat, &id, change).await })
        });
    }

    pub fn set_thread_following(self: Pin<&mut Self>, root_id: &QString, follow: bool) {
        let id = root_id.to_string();
        let at = id.clone();
        self.message_action(&at, move |client, chat| {
            Box::pin(
                async move { api::msgactions::set_following(&client, &chat, &id, follow).await },
            )
        });
    }

    pub fn edit_message_rich(
        self: Pin<&mut Self>,
        message_id: &QString,
        editor_html: &QString,
        quote_json: &QString,
        media_json: &QString,
    ) {
        let id = message_id.to_string();
        // The emoticons, custom emoji and pictures in the box go out in
        // Teams' own form (the edit form gave them back; the picker adds).
        let media: Vec<api::messages::ComposeMedia> =
            serde_json::from_str(&media_json.to_string()).unwrap_or_default();
        let (html, mentions) =
            api::messages::teams_html_with_media(&editor_html.to_string(), &media);
        if html.trim().is_empty() {
            return;
        }
        let quote: Option<api::messages::Quote> =
            serde_json::from_str(&quote_json.to_string()).ok();
        let at = id.clone();
        self.message_action(&at, move |client, chat| {
            Box::pin(async move {
                api::messages::edit_message_html(
                    &client,
                    &chat,
                    &id,
                    &html,
                    quote.as_ref(),
                    Some(&mentions),
                )
                .await
            })
        });
    }

    pub fn delete_message(self: Pin<&mut Self>, message_id: &QString) {
        let id = message_id.to_string();
        deleted_here().lock().unwrap().insert(id.clone());
        let at = id.clone();
        self.message_action(&at, move |client, chat| {
            Box::pin(async move { api::messages::delete_message(&client, &chat, &id).await })
        });
    }

    /// Undo a delete made in this session (Teams' Undo on the tombstone).
    pub fn undo_delete_message(self: Pin<&mut Self>, message_id: &QString) {
        let id = message_id.to_string();
        deleted_here().lock().unwrap().remove(&id);
        let at = id.clone();
        self.message_action(&at, move |client, chat| {
            Box::pin(async move { api::messages::undelete_message(&client, &chat, &id).await })
        });
    }

    /// Run a message change in the open chat, then reload it.
    fn message_action<F>(self: Pin<&mut Self>, message_id: &str, act: F)
    where
        F: FnOnce(
                TeamsClient,
                String,
            ) -> std::pin::Pin<
                Box<dyn std::future::Future<Output = anyhow::Result<()>> + Send>,
            > + Send
            + 'static,
    {
        let chat_id = self.chat_of(message_id);
        if chat_id.is_empty() {
            return;
        }
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let changed = chat_id.clone();
            let result = match TeamsClient::new().await {
                Ok(client) => act(client, chat_id).await,
                Err(e) => Err(e),
            };
            let _ = qt.queue(move |mut this| match result {
                Ok(()) => this.as_mut().reload_where(&changed),
                Err(e) => this
                    .as_mut()
                    .set_status_text(QString::from(short_error(&e).as_str())),
            });
        });
    }

    pub fn toggle_reaction(self: Pin<&mut Self>, message_id: &QString, key: &QString, on: bool) {
        let (message_id, key) = (message_id.to_string(), key.to_string());
        let chat_id = self.chat_of(&message_id);
        if chat_id.is_empty() || message_id.is_empty() {
            return;
        }
        // Adding another skin tone of an emoticon we reacted with replaces
        // that one (Teams: one tone per emoticon).
        let replaces: Option<String> = on
            .then(|| {
                let shown: serde_json::Value = serde_json::from_str(&self.shown_json_of(&chat_id)).ok()?;
                let common = api::messages::common_key(&key);
                let m = shown
                    .as_array()?
                    .iter()
                    .find(|m| m["id"].as_str() == Some(message_id.as_str()))?;
                m["reactions"]
                    .as_array()?
                    .iter()
                    .find(|r| {
                        r["mine"].as_bool() == Some(true)
                            && r["key"].as_str() == Some(common)
                            && r["my_key"].as_str() != Some(key.as_str())
                    })
                    .and_then(|r| r["my_key"].as_str().map(str::to_string))
            })
            .flatten();
        // Adding one moves it to the front of Recent, which roams (Teams'
        // addEmojisInRecent).
        let recent = on.then(|| {
            let now: Vec<String> =
                serde_json::from_str(&self.rust().recent_reactions_json.to_string())
                    .unwrap_or_default();
            api::emoticons::note_recent(&now, &key)
        });
        let mut this = self;
        if let Some(r) = &recent {
            let text = serde_json::to_string(r).unwrap_or_default();
            this.as_mut()
                .set_recent_reactions_json(QString::from(text.as_str()));
        }
        let qt = this.qt_thread();
        let changed = chat_id.clone();
        runtime().spawn(async move {
            // One reaction write at a time: the service rejects concurrent
            // changes to a message's emotions.
            static WRITES: std::sync::OnceLock<tokio::sync::Mutex<()>> = std::sync::OnceLock::new();
            let _turn = WRITES.get_or_init(Default::default).lock().await;
            let result = async {
                let client = TeamsClient::new().await?;
                if let Some(old) = &replaces {
                    let wire = api::emoticons::server_key(old);
                    api::messages::set_reaction(&client, &chat_id, &message_id, wire, false)
                        .await?;
                }
                // The service keys a few emoticons differently (Teams' 77708).
                let wire = api::emoticons::server_key(&key);
                api::messages::set_reaction(&client, &chat_id, &message_id, wire, on).await?;
                if let Some(r) = recent
                    && let Err(e) = api::emoticons::set_recent_reactions(&client, &r).await
                {
                    tracing::warn!("recent reactions not saved: {}", short_error(&e));
                }
                anyhow::Ok(())
            }
            .await;
            let _ = qt.queue(move |mut this| match result {
                Ok(()) => this.as_mut().reload_where(&changed),
                Err(e) => {
                    tracing::warn!("reaction not changed: {}", short_error(&e));
                    // A message at the service's size limit takes no more
                    // reactions (413); Teams' words for it.
                    let text = if format!("{e:#}").contains("HTTP 413") {
                        tr("Current message size limit reached. We can't add any more reactions.")
                    } else {
                        short_error(&e)
                    };
                    this.as_mut().set_status_text(QString::from(text.as_str()));
                }
            });
        });
    }

    pub fn set_ringer(self: Pin<&mut Self>, on: bool) {
        // Main.qml's ringer plays Teams' ringtone (Settings ▸ Calls ▸ Choose
        // a ringtone for you) while this is on.
        if self.rust().ringer_on != on {
            tracing::info!(on, "ringing");
            self.set_ringer_on(on);
        }
    }

    pub fn user_typing(mut self: Pin<&mut Self>) {
        let chat_id = self.rust().current_chat_id.to_string();
        if chat_id.is_empty() {
            return;
        }
        let now = std::time::Instant::now();
        if self
            .rust()
            .last_typing_sent
            .is_some_and(|t| now.duration_since(t).as_secs() < TYPING_SEND_INTERVAL_SECS)
        {
            return;
        }
        self.as_mut().rust_mut().last_typing_sent = Some(now);
        runtime().spawn(async move {
            let result = async {
                let client = TeamsClient::new().await?;
                api::send_typing(&client, &chat_id).await
            }
            .await;
            if let Err(e) = result {
                tracing::debug!("typing indicator failed: {}", short_error(&e));
            }
        });
    }

    fn on_chat_push(mut self: Pin<&mut Self>, ids: Vec<String>) {
        // Waiting in a lobby whose chat already exists: the first push of
        // the lobby chat thread is how its messages reach us (no
        // conversationUpdate then); a meeting thread that is the lobby's
        // chat (meetingChatType "lobby") becomes the call's lobby chat.
        if self.rust().call_state.to_string() == "lobby" && self.rust().call_lobby_thread.is_empty() {
            let main = self.rust().call_thread_id.to_string();
            let candidates: Vec<String> = ids.iter().filter(|i| i.starts_with("19:meeting_") && **i != main).cloned().collect();
            if !candidates.is_empty() {
                let qt = self.qt_thread();
                runtime().spawn(async move {
                    let Ok(client) = TeamsClient::new().await else { return };
                    for id in candidates {
                        let url = format!("{}/v1/threads/{}?view=msnp24Equivalent", client.chat_service_url(), id);
                        let Ok(resp) = client.chat_get(&url).await else { continue };
                        let Ok(v) = resp.json::<serde_json::Value>().await else { continue };
                        if v.pointer("/properties/meetingChatType").and_then(|t| t.as_str()) == Some("lobby") {
                            tracing::info!("lobby chat thread from a chat push");
                            let _ = qt.queue(move |mut this| {
                                if this.rust().call_lobby_thread.is_empty() {
                                    this.as_mut().set_call_lobby_thread(QString::from(id.as_str()));
                                }
                            });
                            break;
                        }
                    }
                });
            }
        }
        let current = self.rust().current_chat_id.to_string();
        let mut list_changed = false;
        // New notifications: refresh Activity (and its badge).
        if ids.iter().any(|i| i == "48:notifications") {
            self.as_mut().load_activity();
        }
        for id in ids.iter().filter(|i| !i.starts_with("48:")) {
            let channel = id.split(';').next().unwrap_or_default().to_string();
            let open: Vec<String> = self
                .rust()
                .thread_windows
                .iter()
                .filter(|t| window_channel(t) == channel.as_str())
                .cloned()
                .collect();
            for t in open {
                self.as_mut().reload_thread_window(t);
            }
        }
        let mut reload = false;
        for id in ids.into_iter().filter(|i| !i.starts_with("48:")) {
            // A thread's push names "<channel>;messageid=<post>": the open
            // channel shows its replies (and, in the Threads layout, their
            // counts and replies also sent to the channel).
            if id == current || id.split(';').next() == Some(current.as_str()) {
                reload = true;
            } else {
                list_changed |= self.as_mut().rust_mut().unread.insert(id);
            }
        }
        if reload {
            self.as_mut().reload_messages();
        }
        if list_changed {
            self.as_mut().publish_chats();
        }
        self.as_mut().reload_chats();
    }

    /// Reload the chat list quietly (new chats, new order), keeping unread
    /// flags. Pushes arriving while a reload runs are folded into it.
    fn reload_chats(self: Pin<&mut Self>) {
        static RUNNING: AtomicBool = AtomicBool::new(false);
        static AGAIN: AtomicBool = AtomicBool::new(false);
        if RUNNING.swap(true, Ordering::SeqCst) {
            AGAIN.store(true, Ordering::SeqCst);
            return;
        }
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let result = load_overview().await;
            let _ = qt.queue(move |mut this| {
                RUNNING.store(false, Ordering::SeqCst);
                match result {
                    Ok((_, chats)) => {
                        this.as_mut().rust_mut().chats = chats;
                        this.as_mut().publish_chats();
                    }
                    Err(e) => tracing::warn!("chat list reload failed: {}", short_error(&e)),
                }
                if AGAIN.swap(false, Ordering::SeqCst) {
                    this.as_mut().reload_chats();
                }
            });
        });
    }

    pub fn refresh(mut self: Pin<&mut Self>) {
        self.as_mut().set_busy(true);
        self.as_mut().set_status_text(QString::from(tr("Loading…")));
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let result = load_overview().await;
            tracing::info!(ok = result.is_ok(), "overview loaded");
            // Your End-to-end encrypted calls setting (Teams reads it at
            // start): 1:1 calls ask for E2EE while it is on.
            runtime().spawn(async {
                if let Ok(client) = TeamsClient::new().await
                    && let Ok(on) = api::preferences::e2ee_calls_enabled(&client).await
                {
                    tracing::info!(on, "end-to-end encrypted calls setting");
                    teams_cli::calling::webrtc_audio::set_prefer_e2ee(on);
                }
            });
            if let Err(e) = &result {
                tracing::warn!("overview failed: {}", short_error(e));
            }
            let _ = qt.queue(move |mut this| {
                this.as_mut().set_busy(false);
                match result {
                    Ok((name, chats)) => {
                        this.as_mut().set_signed_in(true);
                        this.as_mut().set_user_name(QString::from(name.as_str()));
                        this.as_mut().load_profile();
                        this.as_mut().load_engagement();
                        this.as_mut().rust_mut().my_mri = teams_cli::config::Config::load()
                            .ok()
                            .and_then(|c| c.object_id())
                            .map(|oid| format!("8:orgid:{oid}").to_ascii_lowercase());
                        let mri = this.rust().my_mri.clone().unwrap_or_default();
                        this.as_mut().set_user_mri(QString::from(mri.as_str()));
                        this.as_mut().rust_mut().chats = chats;
                        this.as_mut().publish_chats();
                        this.as_mut().set_status_text(QString::default());
                        this.as_mut().start_push();
                        this.as_mut().start_room_mode();
                        this.as_mut().start_presence();
                        this.as_mut().load_server_unread();
                        this.as_mut().load_teams();
                        this.as_mut().folders_load();
                        this.as_mut().load_activity();
                        // Teams' live settings (ECS), as Teams loads them
                        // at start.
                        runtime().spawn(async {
                            let r = async {
                                let client = TeamsClient::new().await?;
                                api::ecs::load(&client, &cache_base()).await
                            }
                            .await;
                            match r {
                                Ok(()) => tracing::info!(
                                    "ECS settings loaded (ring {})",
                                    api::ecs::segment("TeamsRing").unwrap_or_default()
                                ),
                                Err(e) => tracing::warn!("ECS settings: {}", short_error(&e)),
                            }
                            // Write with Copilot needs the licence and the
                            // settings.
                            if let Ok(client) = TeamsClient::new().await {
                                if let Some(t) = client.tenant_id() {
                                    let _ = TENANT_ID.set(t.to_string());
                                }
                                let license = api::ecs::license(&client).await;
                                let state = compose_copilot_state(license.as_ref()).to_string();
                                tracing::info!("compose Copilot: {state}");
                                if let Some(qt) = QT_THREAD.get() {
                                    let _ = qt.queue(move |mut this| this.as_mut().set_compose_copilot_json(QString::from(state.as_str())));
                                }
                            }
                            // The apps that unfurl links (app link cards).
                            let r = async {
                                let client = TeamsClient::new().await?;
                                api::link_unfurl::load_index(&client, &cache_base()).await
                            }
                            .await;
                            if let Err(e) = r {
                                tracing::warn!("app link index: {}", short_error(&e));
                            }
                        });
                    }
                    Err(e) => {
                        this.as_mut().set_signed_in(false);
                        this.as_mut()
                            .set_status_text(QString::from(short_error(&e).as_str()));
                    }
                }
            });
        });
    }

    pub fn select_chat(mut self: Pin<&mut Self>, chat_id: &QString, chat_name: &QString) {
        if self.as_mut().rust_mut().unread.remove(&chat_id.to_string()) {
            self.as_mut().publish_chats();
        }
        self.as_mut().rust_mut().typers.clear();
        self.as_mut().rust_mut().reply_quote = None;
        self.as_mut().rust_mut().next_importance.clear();
        self.as_mut().rust_mut().next_url_preview = None;
        self.as_mut().rust_mut().next_url_preview_on_send = false;
        self.as_mut().rust_mut().next_app_card = None;
        self.as_mut().rust_mut().next_post = None;
        self.as_mut().rust_mut().next_schedule_ms = None;
        self.as_mut().rust_mut().typing_generation += 1;
        self.as_mut().set_typing_text(QString::default());
        self.as_mut().set_typing_avatar(QString::default());
        self.as_mut().set_typing_avatar_id(QString::default());
        self.as_mut().rust_mut().newest_message_id = None;
        read_at_open().lock().unwrap().remove(&chat_id.to_string());
        self.as_mut().set_current_chat_id(chat_id.clone());
        self.as_mut().set_current_chat_name(chat_name.clone());
        self.as_mut().set_messages_json(QString::from("[]"));
        self.as_mut().reload_messages();
        self.as_mut().load_chat_members();
        self.as_mut().load_chat_meeting();
        self.as_mut().load_scheduled();
        if chat_id.to_string().ends_with("@thread.tacv2") {
            self.as_mut().check_channel_layout(chat_id.to_string());
        }
    }

    /// A channel's layout as the chat service has it, when the teams list
    /// says otherwise (or nothing): Teams lays the channel out by it.
    fn check_channel_layout(self: Pin<&mut Self>, channel: String) {
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let Ok(client) = TeamsClient::new().await else { return };
            let Ok(Some(modality)) = api::messages::thread_modality(&client, &channel).await else { return };
            let _ = qt.queue(move |mut this| {
                let mut teams: serde_json::Value = serde_json::from_str(&this.rust().teams_json.to_string()).unwrap_or_default();
                let mut changed = false;
                for t in teams.as_array_mut().into_iter().flatten() {
                    for c in t["channels"].as_array_mut().into_iter().flatten() {
                        if c["id"].as_str() == Some(channel.as_str()) && c["layout"].as_str() != Some(modality.as_str()) {
                            c["layout"] = json!(modality);
                            changed = true;
                        }
                    }
                }
                this.as_mut().rust_mut().channel_layouts.insert(channel.clone(), modality.clone());
                if changed {
                    tracing::info!(%modality, "channel layout from the chat service");
                    this.as_mut().set_teams_json(QString::from(teams.to_string().as_str()));
                }
            });
        });
    }

    /// The open chat's scheduled messages (from your 48:drafts stream).
    fn load_scheduled(mut self: Pin<&mut Self>) {
        let chat_id = self.rust().current_chat_id.to_string();
        self.as_mut().set_scheduled_json(QString::from("[]"));
        if chat_id.is_empty() || chat_id.starts_with("48:") {
            return;
        }
        let me = self.rust().my_mri.clone().unwrap_or_default();
        let name = self.rust().user_name.to_string();
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let result = async {
                let client = TeamsClient::new().await?;
                api::drafts::page(&client).await
            }
            .await;
            let _ = qt.queue(move |mut this| {
                // Other devices' drafts come in with it (Teams' drafts sync).
                if let Ok(page) = &result {
                    this.as_mut().apply_roamed(page);
                }
                let result = result.map(|page| api::scheduled::scheduled_from(&page, &me, &name));
                if this.rust().current_chat_id.to_string() != chat_id {
                    return;
                }
                match result {
                    Ok(list) => {
                        let mine: Vec<_> = list.into_iter().filter(|s| s.conversation == chat_id).collect();
                        let json = serde_json::to_string(&mine).unwrap_or_else(|_| "[]".into());
                        this.as_mut().set_scheduled_json(QString::from(json.as_str()));
                    }
                    Err(e) => tracing::debug!("scheduled messages unavailable: {}", short_error(&e)),
                }
            });
        });
    }

    pub fn set_next_schedule(mut self: Pin<&mut Self>, ms: &QString) {
        self.as_mut().rust_mut().next_schedule_ms = ms.to_string().parse::<i64>().ok().filter(|m| *m > 0);
    }

    pub fn find_in_chat(mut self: Pin<&mut Self>, key: &QString, thread: &QString, keywords: &QString, filters_json: &QString, from: i32) {
        let key = key.to_string();
        let thread = thread.to_string();
        let keywords = keywords.to_string().trim().to_string();
        let filters: api::find::Filters = serde_json::from_str(&filters_json.to_string()).unwrap_or_default();
        let from = from.max(0) as usize;
        // Earlier pages stay while the next one loads.
        let mut shown: serde_json::Value = serde_json::from_str(&self.rust().find_json.to_string()).unwrap_or_default();
        if from == 0 || shown["key"] != key.as_str() {
            shown = json!({ "key": key, "hits": [], "terms": [], "total": 0, "more": false });
        }
        shown["loading"] = true.into();
        shown["error"] = "".into();
        self.as_mut().rust_mut().find_key = key.clone();
        self.as_mut().set_find_json(QString::from(shown.to_string().as_str()));
        if thread.is_empty() || (keywords.is_empty() && filters.from_mail.is_empty() && filters.start.is_empty() && !filters.attachment && !filters.mentions) {
            shown["loading"] = false.into();
            self.as_mut().set_find_json(QString::from(shown.to_string().as_str()));
            return;
        }
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let result = async {
                let client = TeamsClient::new().await?;
                let oid = client.object_id().unwrap_or_default();
                let tenant = client.tenant_id().unwrap_or_default();
                let mut filters = filters;
                // A channel's Files search names its folder.
                if filters.files && thread.ends_with("@thread.tacv2") && filters.channel_path.is_empty() {
                    let folder = api::drive::channel_folder(&client, &filters.channel_group, &thread).await?;
                    filters.channel_path = api::find::folder_path(&folder.web_url);
                }
                api::find::search(&client, &thread, &keywords, &filters, from, &api::find::local_timezone(), &oid, &tenant).await
            }
            .await;
            let _ = qt.queue(move |mut this| {
                if this.rust().find_key != key {
                    return;
                }
                let mut shown = shown;
                shown["loading"] = false.into();
                match result {
                    Ok(found) => {
                        let mut hits = shown["hits"].as_array().cloned().unwrap_or_default();
                        hits.extend(found.hits.iter().map(|h| json!(h)));
                        shown["hits"] = hits.into();
                        shown["total"] = found.total.into();
                        shown["more"] = found.more.into();
                        shown["terms"] = json!(found.terms);
                    }
                    Err(e) => {
                        tracing::warn!("find in chat failed: {}", short_error(&e));
                        shown["error"] = short_error(&e).into();
                    }
                }
                this.as_mut().set_find_json(QString::from(shown.to_string().as_str()));
            });
        });
    }

    pub fn feedback_issue_url(self: Pin<&mut Self>, report_json: &QString) -> QString {
        let mut report: teams_cli::feedback::Report = serde_json::from_str(&report_json.to_string()).unwrap_or_default();
        // The report goes to GitHub in English, whatever the app language:
        // where it was sent from, as OST's English.
        report.area = teams_cli::i18n::english(&report.area);
        report.context = teams_cli::i18n::english(&report.context);
        let logs = if report.share_logs {
            std::fs::read_to_string(crate::log_path())
                .map(|l| teams_cli::feedback::masked_tail(&l, 400))
                .unwrap_or_default()
        } else {
            String::new()
        };
        let version = format!("OST desktop {}", env!("CARGO_PKG_VERSION"));
        let url = teams_cli::feedback::issue_url(&report, &version, &teams_cli::feedback::os_name(), &logs);
        // The diagnostic data a report carries (View Diagnostic Data).
        api::ddv::record("Ost.Feedback.Report", json!({
            "kind": report.kind, "area": report.area, "version": version, "os": teams_cli::feedback::os_name(),
            "logsIncluded": !logs.is_empty(), "contact": report.contact, "files": report.files.len(),
            "destination": teams_cli::feedback::repo(), "url": url,
        }));
        // GitHub takes pictures by paste: the first one goes on the clipboard.
        let picture = report.files.iter().find(|f| {
            let f = f.to_ascii_lowercase();
            [".png", ".jpg", ".jpeg", ".gif", ".bmp", ".webp"].iter().any(|e| f.ends_with(e))
        });
        if let Some(Ok(p)) = picture.map(|p| std::ffi::CString::new(p.as_str())) {
            // SAFETY: a NUL-terminated path, read by Qt before returning.
            unsafe { ost_set_clipboard_image(p.as_ptr()) };
        }
        QString::from(url.as_str())
    }

