    pub fn meeting_board_frame_url(&self, stored: &QString, params: &QString) -> QString {
        let p: serde_json::Value = serde_json::from_str(&params.to_string()).unwrap_or_default();
        let s = |k: &str| p.get(k).and_then(|v| v.as_str()).unwrap_or_default().to_string();
        let url = api::app_host::board_frame_url(
            &stored.to_string(),
            p.get("tabStart").and_then(|v| v.as_i64()).unwrap_or_else(|| chrono::Utc::now().timestamp_millis()),
            &s("correlation"),
            p.get("initiator").and_then(|v| v.as_bool()).unwrap_or(false),
            &s("meetingId"),
            &s("user"),
            &s("tenant"),
        );
        QString::from(url.unwrap_or_else(|| stored.to_string()).as_str())
    }

    #[allow(clippy::too_many_arguments)]
    pub fn app_host_request(self: Pin<&mut Self>, app_id: &QString, thread: &QString, team_thread: &QString, tab_id: &QString, kind: &QString, id: &QString, payload: &QString) {
        let (app, thread, team, tab, kind, id, payload) =
            (app_id.to_string(), thread.to_string(), team_thread.to_string(), tab_id.to_string(), kind.to_string(), id.to_string(), payload.to_string());
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let p: serde_json::Value = serde_json::from_str(&payload).unwrap_or_default();
            let s = |k: &str| p.get(k).and_then(|v| v.as_str()).unwrap_or_default().to_string();
            let answer = match kind.as_str() {
                "context" => match TeamsClient::new().await {
                    Ok(c) => match api::app_host::context(&c, &app, &thread, &team).await {
                        Ok(mut v) => {
                            // Copilot's context also names your OneDrive site.
                            if p.get("mySite").and_then(|b| b.as_bool()).unwrap_or(false)
                                && let Some((domain, path)) = api::app_host::my_site(&c).await
                            {
                                v["mySiteDomain"] = json!(domain);
                                v["mySitePath"] = json!(path);
                            }
                            json!({ "context": v, "deepNaa": api::app_host::deep_naa(&app) }).to_string()
                        }
                        Err(e) => json!({ "error": short_error(&e) }).to_string(),
                    },
                    Err(e) => json!({ "error": short_error(&e) }).to_string(),
                },
                // A personal app from the app bar: its personal tab (Teams'
                // address with placeholders, entity id) and whether Teams
                // hides its header.
                "personalTab" => {
                    let r = async {
                        let c = TeamsClient::new().await?;
                        let f = api::app_host::facts(&c, &app).await?;
                        let tab = api::app_host::personal_tab(&f, &s("entity")).cloned().context("The app has no personal tab")?;
                        anyhow::Ok(json!({ "tab": tab, "fullScreen": f.full_screen }))
                    }
                    .await;
                    match r {
                        Ok(v) => v.to_string(),
                        Err(e) => {
                            tracing::warn!("personal tab of {app}: {}", short_error(&e));
                            json!({ "error": short_error(&e) }).to_string()
                        }
                    }
                }
                // teams.fullTrust.joinedTeams.getUserJoinedTeams (Shifts).
                "joinedTeams" => {
                    let r = async { api::teams::list_teams_csa(&TeamsClient::new().await?).await }.await;
                    api::app_host::joined_teams_from(&r.unwrap_or_default()).to_string()
                }
                // The token Teams posts with a server-rendered app's first
                // page (Copilot): brokered for the app's own Azure AD app
                // and resource, as for the page's NAA GetToken. Never logged.
                "ssrToken" => {
                    let r = async {
                        let c = TeamsClient::new().await?;
                        let f = api::app_host::facts(&c, &app).await?;
                        anyhow::ensure!(!f.web_app_id.is_empty() && f.web_app_resource.starts_with("https://"), "No web application for the app");
                        let scope = format!("{}/.default", f.web_app_resource.trim_end_matches('/'));
                        teams_cli::auth::oauth::brokered_token(&f.web_app_id, &s("origin"), &scope, None).await
                    }
                    .await;
                    match r {
                        Ok((t, _)) => json!({ "token": t }).to_string(),
                        Err(e) => {
                            tracing::warn!("server-rendering token for {app} failed: {}", short_error(&e));
                            json!({ "error": short_error(&e) }).to_string()
                        }
                    }
                }
                // Teams' NAA broker: trusted when the asking frame is one
                // of the app's valid domains, or one the app added.
                "naa" => {
                    let origin = s("origin");
                    let facts = match TeamsClient::new().await {
                        Ok(c) => api::app_host::facts(&c, &app).await.unwrap_or_default(),
                        Err(_) => Default::default(),
                    };
                    // Origins an app adds count for Microsoft's own apps
                    // only (Teams' isRestrictedToMicrosoftOwnedApps).
                    let requested = facts.microsoft_owned && p.get("requestedTrust").and_then(|v| v.as_bool()).unwrap_or(false);
                    let trusted = requested || api::app_host::origin_valid_for_app(&origin, &facts.valid_domains);
                    teams_cli::auth::broker::execute(&s("request"), &origin, trusted).await
                }
                "sso" => {
                    let asked: Vec<String> = p
                        .get("resources")
                        .and_then(|a| a.as_array())
                        .map(|a| a.iter().filter_map(|v| v.as_str().map(str::to_string)).collect())
                        .unwrap_or_default();
                    let r = async {
                        // Teams' calendar (Outlook's hosted calendar): its own
                        // app's token through Teams' broker, for Outlook.
                        if app.eq_ignore_ascii_case("ef56c0de-36fc-4ef8-b417-3d82ba9d073c") {
                            let resource = asked.first().cloned().unwrap_or_else(|| "https://outlook.office.com".into());
                            let host = reqwest::Url::parse(&resource).ok().and_then(|u| u.host_str().map(str::to_ascii_lowercase)).unwrap_or_default();
                            anyhow::ensure!(
                                resource.starts_with("https://") && [".office.com", ".skype.com", ".microsoft.com"].iter().any(|d| host.ends_with(d)),
                                "Invalid resource"
                            );
                            // Teams' own services (the calling stack's ic3,
                            // for the form's Teams meeting): Teams' token.
                            if !(resource.starts_with("https://outlook.office.com") || resource.starts_with("https://outlook.office365.com")) {
                                return teams_cli::auth::oauth::access_token_for(&format!("{}/.default", resource.trim_end_matches('/'))).await;
                            }
                            let (t, _) = teams_cli::auth::oauth::brokered_token(
                                api::calendar::HOSTED_CALENDAR_APP,
                                "https://outlook.office.com",
                                &format!("{}/.default", resource.trim_end_matches('/')),
                                None,
                            )
                            .await?;
                            return Ok(t);
                        }
                        let c = TeamsClient::new().await?;
                        let f = api::app_host::facts(&c, &app).await?;
                        let resource = api::app_host::sso_resource(&f, &s("teamSiteDomain"), p.get("resources"))?;
                        teams_cli::auth::oauth::access_token_for(&format!("{}/.default", resource.trim_end_matches('/'))).await
                    }
                    .await;
                    match r {
                        Ok(t) => json!({ "token": t }).to_string(),
                        Err(e) => {
                            tracing::warn!(?asked, "getAuthToken for {app} failed: {}", short_error(&e));
                            json!({ "error": "FailedToGetToken" }).to_string()
                        }
                    }
                }
                // Share to Outlook: the draft Teams' middle tier makes of
                // the conversation, and the compose page Teams frames.
                "stoCreate" => {
                    let r = async { api::app_host::share_to_outlook_email(&TeamsClient::new().await?, &thread, &s("messageId"), &s("bodyType")).await }.await;
                    match r {
                        Ok(id) => json!({ "emailId": id, "url": api::app_host::share_to_outlook_compose_url(&id, "en-us") }).to_string(),
                        Err(e) => {
                            tracing::warn!("share to Outlook draft failed: {}", short_error(&e));
                            json!({ "error": short_error(&e) }).to_string()
                        }
                    }
                }
                // Closed without sending: Teams discards the draft.
                "stoDiscard" => {
                    let r = async { api::app_host::share_to_outlook_discard(&TeamsClient::new().await?, &s("emailId")).await }.await;
                    if let Err(e) = &r {
                        tracing::warn!("discarding the share to Outlook draft failed: {}", short_error(e));
                    }
                    json!({ "ok": r.is_ok() }).to_string()
                }
                // Immersive Reader: Teams' own token for the reader service
                // (immersiveReaderServiceUrlV2). Never logged.
                "irToken" => match teams_cli::auth::oauth::access_token_for("https://immersivereader.cloud.microsoft/.default").await {
                    Ok(t) => json!({ "token": t }).to_string(),
                    Err(e) => {
                        tracing::warn!("Immersive Reader token failed: {}", short_error(&e));
                        // Teams falls back to "anonymous".
                        json!({ "token": "anonymous" }).to_string()
                    }
                },
                // A Word, Excel or PowerPoint file in Office for the web,
                // as Teams' "Teams" choice opens it: the Office app and the
                // file's subEntityId.
                "officeOpen" => {
                    let r = async {
                        let c = TeamsClient::new().await?;
                        api::office_open::open_info(&c, &s("url"), &s("driveId"), &s("itemId"), &s("caller")).await
                    }
                    .await;
                    match r {
                        Ok(v) => v.to_string(),
                        Err(e) => {
                            tracing::warn!("opening the file in OST failed: {}", short_error(&e));
                            json!({ "error": short_error(&e) }).to_string()
                        }
                    }
                }
                // getChatMembers: the chat's members' sign-in names.
                "chatMembers" => {
                    let r = async { api::tab_add::chat_member_upns(&TeamsClient::new().await?, &thread).await }.await;
                    json!({ "upns": r.unwrap_or_default() }).to_string()
                }
                // A meeting chat's Whiteboard: the meeting's own board
                // (Teams' fluidboard), and keeping the board Whiteboard
                // reports (changeWhiteboardUrl).
                "board" => {
                    let r = async { api::app_host::meeting_board(&TeamsClient::new().await?, &thread, &s("organizer"), &s("title")).await }.await;
                    match r {
                        Ok(u) => json!({ "url": u }).to_string(),
                        Err(e) => {
                            tracing::warn!("meeting board for {thread} failed: {}", short_error(&e));
                            json!({ "error": short_error(&e) }).to_string()
                        }
                    }
                }
                "saveBoard" => {
                    let r = async { api::app_host::save_meeting_board(&TeamsClient::new().await?, &thread, &s("organizer"), &s("url")).await }.await;
                    if let Err(e) = &r {
                        tracing::warn!("saving the meeting board for {thread} failed: {}", short_error(e));
                    }
                    json!({ "ok": r.is_ok() }).to_string()
                }
                "saveTab" => {
                    let settings = p.get("settings").cloned().unwrap_or_default();
                    let r = async { api::tab_add::set_settings(&TeamsClient::new().await?, &thread, &tab, &settings).await }.await;
                    match r {
                        Ok(()) => json!({ "ok": true }).to_string(),
                        Err(e) => {
                            tracing::warn!("saving tab {tab} settings failed: {}", short_error(&e));
                            json!({ "ok": false, "error": short_error(&e) }).to_string()
                        }
                    }
                }
                _ => json!({ "error": "unknown" }).to_string(),
            };
            let _ = qt.queue(move |mut this| this.as_mut().app_host_reply(QString::from(id.as_str()), QString::from(answer.as_str())));
        });
    }

