    pub fn drive_action(mut self: Pin<&mut Self>, op: &QString, item_json: &QString, args_json: &QString) {
        let op = op.to_string();
        let item: api::drive::DriveItem = serde_json::from_str(&item_json.to_string()).unwrap_or_default();
        let args: serde_json::Value = serde_json::from_str(&args_json.to_string()).unwrap_or(json!({}));
        // A zip waits for its place when asked to.
        if op.rsplit(':').next() == Some("zip") && ask_where_to_save() {
            let more: Vec<api::drive::DriveItem> = serde_json::from_value(args["more"].clone()).unwrap_or_default();
            let items: Vec<api::drive::DriveItem> = std::iter::once(item).chain(more).collect();
            let name = args["name"].as_str().filter(|n| !n.is_empty()).map(str::to_string).unwrap_or_else(|| format!("{}.zip", items[0].name));
            self.as_mut().ask_save(PendingSave::Zip { op, items, name: name.clone() }, &name);
            return;
        }
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let s = |k: &str| args[k].as_str().unwrap_or_default().to_string();
            let sp = api::sharing::ItemRef { site: item.sp_site.clone(), list: item.sp_list.clone(), item: item.sp_item.clone() };
            // "<tag>:<op>": each Files view takes only its own replies.
            let kind = op.rsplit(':').next().unwrap_or_default().to_string();
            let result: anyhow::Result<serde_json::Value> = async {
                let client = TeamsClient::new().await?;
                Ok(match kind.as_str() {
                    "libraries" => json!(api::drive::libraries(&client).await?),
                    // Quick access (pinned, then recent libraries) and its
                    // pin / unpin.
                    "quick_access" => json!(api::quick_access::items(&client).await?),
                    "quick_pin" => {
                        let lib: api::quick_access::QuickLibrary = serde_json::from_value(args["lib"].clone())?;
                        let pin = args["pin"].as_bool().unwrap_or(true);
                        api::quick_access::set_pinned(&client, &lib, pin).await?;
                        json!({ "title": lib.title, "pin": pin, "items": api::quick_access::items(&client).await.unwrap_or_default() })
                    }
                    "rename" => {
                        api::drive::rename(&client, &item.drive_id, &item.id, &s("name")).await?;
                        json!(null)
                    }
                    "move" | "copy" | "duplicate" => {
                        // The item, and any others selected with it ("more").
                        let more: Vec<api::drive::DriveItem> =
                            serde_json::from_value(args["more"].clone()).unwrap_or_default();
                        let all: Vec<&api::drive::DriveItem> = std::iter::once(&item).chain(more.iter()).collect();
                        let mut sources = Vec::new();
                        for it in &all {
                            let r = api::sharing::ItemRef { site: it.sp_site.clone(), list: it.sp_list.clone(), item: it.sp_item.clone() };
                            sources.push(api::copy_jobs::absolute_url(&r).await?);
                        }
                        let (dest, names) = if kind == "duplicate" {
                            let parent = sources[0].rsplit_once('/').map(|(p, _)| p.to_string()).unwrap_or_default();
                            (parent, all.iter().map(|it| api::copy_jobs::duplicate_name(&it.name, it.is_folder)).collect())
                        } else {
                            (api::copy_jobs::folder_url(&s("dest")), Vec::new())
                        };
                        api::copy_jobs::run(&sp.site, &sources, &dest, kind == "move", &names).await?;
                        json!(null)
                    }
                    "open_app" => json!({ "path": api::drive::local_copy(&client, &item).await?.display().to_string() }),
                    "preview" => json!(api::drive::preview(&client, &item).await?),
                    // Add shortcut ▸ Shortcuts / My files / a folder.
                    "shortcut" => {
                        let me_root = api::drive::root(&client, "").await?;
                        let personal = me_root.web_url.split('/').take(3).collect::<Vec<_>>().join("/");
                        let place = match s("place").as_str() {
                            "shortcuts" => api::copy_jobs::ShortcutPlace::Shortcuts,
                            "myfiles" => api::copy_jobs::ShortcutPlace::MyFiles,
                            _ => api::copy_jobs::ShortcutPlace::Folder { site: s("site"), drive: s("drive_id"), folder: s("folder") },
                        };
                        // A file's shortcut is named without its extension, as OneDrive names it.
                        let name = if item.is_folder { item.name.clone() } else { std::path::Path::new(&item.name).file_stem().and_then(|n| n.to_str()).unwrap_or(&item.name).to_string() };
                        api::copy_jobs::add_shortcut(&sp, &name, &personal, &place).await?;
                        json!(null)
                    }
                    "folder_color" => {
                        let url = api::copy_jobs::absolute_url(&sp).await?;
                        api::copy_jobs::stamp_color(&sp.site, &url, &s("code")).await?;
                        json!({ "code": s("code") })
                    }
                    // Request files: the upload link, emailed when people are given.
                    "file_request" => {
                        let people: Vec<serde_json::Value> = args["people"].as_array().cloned().unwrap_or_default();
                        let (url, share_id) = api::sharing::file_request(&sp, &s("description"), &people, &s("message")).await?;
                        json!({ "url": url, "share_id": share_id, "sent": !people.is_empty() })
                    }
                    // Download of a folder or several items: one zip from
                    // OneDrive's media service, into the download folder.
                    "zip" => {
                        let more: Vec<api::drive::DriveItem> = serde_json::from_value(args["more"].clone()).unwrap_or_default();
                        let all: Vec<api::drive::DriveItem> = std::iter::once(item.clone()).chain(more).collect();
                        let dir = download_dir().ok_or_else(|| anyhow::anyhow!("No download folder"))?;
                        let name = s("name");
                        let path = api::zip_download::download(&all, &dir, Some(name.as_str()).filter(|n| !n.is_empty())).await?;
                        json!({ "path": path.display().to_string(), "name": path.file_name().and_then(|n| n.to_str()).unwrap_or_default() })
                    }
                    "thumb" => json!({ "id": item.id, "path": api::drive::thumbnail_sized(&client, &item, &s("size")).await?.map(|p| format!("file://{}", p.display())).unwrap_or_default() }),
                    // Version history: the list (with pictures' ids), and
                    // a version restored or sent to the recycle bin.
                    "versions" => {
                        let file = api::copy_jobs::absolute_url(&sp).await?;
                        let mut list = api::versions::list(&sp.site, &file).await?;
                        let emails: Vec<String> = list.iter().map(|v| v.by_email.clone()).collect();
                        let ids = api::sharing::object_ids(&client, &emails).await;
                        for v in &mut list {
                            v.by_oid = ids.get(&v.by_email.to_ascii_lowercase()).cloned().unwrap_or_default();
                        }
                        json!(list)
                    }
                    // The Details pane: activity, bell, More details, who
                    // has access (the share dialog's call) and the picture.
                    "details" => {
                        let me = client.user_principal_name().unwrap_or_default();
                        let (details, sharing, thumb) = tokio::join!(
                            api::item_details::load(&item, &me),
                            async {
                                let mut i = api::sharing::info(&sp).await?;
                                api::sharing::with_object_ids(&client, &mut i).await;
                                anyhow::Ok(i)
                            },
                            api::drive::thumbnail(&client, &item)
                        );
                        let details = details?;
                        // Comment authors' directory ids, for their pictures.
                        let emails: Vec<String> = details.activities.iter().map(|a| a.author_email.clone()).filter(|e| !e.is_empty()).collect();
                        let oids = api::sharing::object_ids(&client, &emails).await;
                        let (people, links, direct) = match sharing {
                            // The owner (listed first) isn't shown; people
                            // with direct access are, and a link circle when
                            // there are links.
                            Ok(i) => (
                                i.people.iter().skip(1).filter(|p| p.direct).map(|p| json!({ "name": p.name, "oid": p.oid })).collect::<Vec<_>>(),
                                !i.links.is_empty(),
                                i.direct_url.clone(),
                            ),
                            Err(_) => (Vec::new(), false, String::new()),
                        };
                        json!({ "details": details, "people": people, "links": links, "direct_url": direct, "oids": oids,
                                "thumbnail": thumb.ok().flatten().map(|p| format!("file://{}", p.display())).unwrap_or_default() })
                    }
                    "notify" => {
                        let file = api::copy_jobs::absolute_url(&sp).await?;
                        api::item_details::set_notify(&item, &file, args["on"].as_bool().unwrap_or(true)).await?;
                        json!(null)
                    }
                    "comment" => {
                        api::item_details::add_comment(&item, &s("text")).await?;
                        json!(null)
                    }
                    // The Details pane with nothing selected: the folder's
                    // activity.
                    "folder_details" => {
                        let (d, i) = (s("drive_id"), s("item_id"));
                        let here = if i.is_empty() { api::drive::root(&client, &d).await? } else { api::drive::item(&client, &d, &i).await? };
                        let host = here.sp_site.split('/').take(3).collect::<Vec<_>>().join("/");
                        let me = client.user_principal_name().unwrap_or_default();
                        json!({ "activities": api::item_details::folder_activity(&host, &here.drive_id, &i, &me).await? })
                    }
                    "delete_comment" => {
                        api::item_details::delete_comment(&item, &s("id")).await?;
                        json!(null)
                    }
                    // Edit comment, and the Reply box under a comment.
                    "edit_comment" => {
                        api::item_details::edit_comment(&item, &s("id"), &s("text")).await?;
                        json!(null)
                    }
                    "reply_comment" => {
                        api::item_details::add_reply(&item, &s("id"), &s("text")).await?;
                        json!(null)
                    }
                    "restore_version" | "delete_version" => {
                        let file = api::copy_jobs::absolute_url(&sp).await?;
                        api::versions::act(&sp.site, &file, &s("label"), kind == "restore_version").await?;
                        json!(null)
                    }
                    // The Move/Copy picker's other places (folders only
                    // can be picked): Shared, Favorites, People (who shared
                    // folders), Meetings; and its search and New folder.
                    "picker_place" => {
                        let folders = |v: Vec<api::drive::DriveItem>| v.into_iter().filter(|i| i.is_folder).collect::<Vec<_>>();
                        match s("place").as_str() {
                            "shared" => json!({ "items": folders(api::drive::shared_with_me(&client).await?) }),
                            "favorites" => json!({ "items": folders(api::drive::favorites(&client).await?) }),
                            "meetings" => json!({ "items": folders(api::drive::meetings(&client).await?) }),
                            "people" => json!({ "people": api::drive::by_people(&client).await?.into_iter()
                                .map(|(name, items)| json!({ "name": name, "items": folders(items) }))
                                .collect::<Vec<_>>() }),
                            other => anyhow::bail!("unknown place {other}"),
                        }
                    }
                    // Teams' Attach: the popover's files (recent-file
                    // suggestions, given the conversation's last messages,
                    // or a search), the cloud file picker's Home and other
                    // places (files too), and a picked file read for the
                    // compose box (its default link and its picture).
                    "attach_suggest" => {
                        let me = client.object_id().unwrap_or_default();
                        let chat = s("chat_id");
                        let others = if chat.is_empty() { Vec::new() } else { api::files::member_oids(&client, &chat).await.unwrap_or_default() };
                        let everyone: Vec<String> = std::iter::once(me).chain(others).collect();
                        let context: Vec<serde_json::Value> = args["context"].as_array().into_iter().flatten().map(|m| {
                            let from = m["sender"].as_str().unwrap_or_default();
                            let to: Vec<String> = everyone.iter().filter(|o| !o.eq_ignore_ascii_case(from)).cloned().collect();
                            api::cloud_attach::context_message(m["id"].as_str().unwrap_or_default(), m["text"].as_str().unwrap_or_default(), from, m["time"].as_str().unwrap_or_default(), &to)
                        }).collect();
                        json!({ "query": s("query"), "items": api::cloud_attach::suggest(&s("query"), &json!(context)).await? })
                    }
                    "attach_recent" => json!({ "items": api::cloud_attach::recent(&client).await? }),
                    "attach_place" => {
                        let now = chrono::Local::now();
                        let deco = |v: Vec<api::drive::DriveItem>| v.iter().map(|it| api::list_rows::decorate(it, None, now)).collect::<Vec<_>>();
                        match s("place").as_str() {
                            "shared" => json!({ "items": deco(api::drive::shared_with_me(&client).await?) }),
                            "favorites" => json!({ "items": deco(api::drive::favorites(&client).await?) }),
                            "meetings" => json!({ "items": api::cloud_attach::meeting_files(&client).await? }),
                            // Pictures and videos (not SharePoint's own
                            // "__siteIcon__" pictures).
                            "media" => json!({ "items": deco(api::drive::media(&client).await?.into_iter().filter(|i| !i.name.starts_with("__")).collect()) }),
                            "people" => {
                                let order = api::cloud_attach::collaborators(&client).await.unwrap_or_default();
                                let me = client.display_name().unwrap_or_default();
                                json!({ "people": api::cloud_attach::order_people(api::drive::by_people(&client).await?, &order, &me).into_iter()
                                    .map(|(name, items)| json!({ "name": name, "items": deco(items) }))
                                    .collect::<Vec<_>>() })
                            }
                            // A channel's folder ("Browse Teams and Channels").
                            "channel" => {
                                json!({ "folder": api::drive::channel_folder(&client, &s("team_id"), &s("channel_id")).await? })
                            }
                            other => anyhow::bail!("unknown place {other}"),
                        }
                    }
                    // A message's file card: the file as a Files item (for
                    // Share, Copy link and Download) and whether it is a
                    // favorite; then Favorite / Unfavorite as Teams does.
                    "card_item" => {
                        let found = api::drive::item_by_url(&client, &s("url")).await?;
                        let same = |i: &api::drive::DriveItem| i.id == found.id || i.web_url.eq_ignore_ascii_case(&found.web_url);
                        let favorite = api::drive::favorites(&client).await.map(|l| l.iter().any(same)).unwrap_or(false);
                        json!({ "url": s("url"), "item": found, "favorite": favorite })
                    }
                    "card_favorite" => {
                        let on = args["on"].as_bool().unwrap_or(true);
                        api::drive::set_favorite_by_url(&s("site"), &s("url"), on).await?;
                        json!({ "url": s("url"), "name": s("name"), "on": on })
                    }
                    // The compose card's Link settings, applied: the chosen
                    // link made now (in a chat, "People currently in this
                    // chat" names its members), as OneDrive's Link settings
                    // does for Teams.
                    "attach_link" => {
                        let r = api::sharing::ItemRef { site: s("site"), list: s("list"), item: s("item") };
                        let scope = args["scope"].as_i64().unwrap_or(4);
                        let people: Vec<serde_json::Value> = if scope == 4 {
                            api::cloud_attach::chat_people(&client, &s("chat_id")).await.iter().map(|(e, n, o)| api::sharing::picker_entry(e, n, o)).collect()
                        } else {
                            Vec::new()
                        };
                        let body = api::sharing::compose_link_body(scope, args["edit"].as_bool().unwrap_or(true), &s("expiration"), &s("password"), &people);
                        let (url, share_id) = api::sharing::create_link_for(&r, &body).await?;
                        json!({ "url": url, "share_id": share_id, "scope": api::cloud_attach::permission_scope(scope) })
                    }
                    "attach_prepare" => {
                        let f = api::cloud_attach::prepare(&client, &item).await?;
                        let pic = api::drive::DriveItem { id: f.item_id.clone(), drive_id: f.drive_id.clone(), ..Default::default() };
                        let thumb = api::drive::thumbnail_sized(&client, &pic, "c960x540").await.ok().flatten();
                        json!({ "file": f, "thumbnail": thumb.map(|p| format!("file://{}", p.display())).unwrap_or_default() })
                    }
                    "picker_search" => json!({ "query": s("query"), "all": args["all"].as_bool().unwrap_or(false), "dates": s("dates"),
                        "items": api::drive::search_folders(&client, &s("query"), args["all"].as_bool().unwrap_or(false), api::drive::date_filter_days(&s("dates"))).await? }),
                    "picker_new_folder" => json!(api::drive::new_folder(&client, &s("drive_id"), &s("item_id"), &s("name")).await?),
                    // The cloud file picker's command bar: Create a folder
                    // (with its colour) and Upload (files, or a folder and
                    // what is in it) into the folder shown.
                    "picker_create_folder" => {
                        let (d, i) = (s("drive_id"), s("item_id"));
                        let here = if i.is_empty() { api::drive::root(&client, &d).await? } else { api::drive::item(&client, &d, &i).await? };
                        let color = args["color"].as_u64().unwrap_or(0) as usize;
                        if color == 0 {
                            json!(api::drive::new_folder(&client, &d, &i, &s("name")).await?)
                        } else {
                            api::cloud_attach::create_folder(&here.web_url, &s("name"), color).await?;
                            json!({ "name": s("name") })
                        }
                    }
                    "picker_upload" => {
                        let (d, i) = (s("drive_id"), s("item_id"));
                        let mut n = 0;
                        for p in args["paths"].as_array().into_iter().flatten().filter_map(|p| p.as_str()) {
                            let p = std::path::PathBuf::from(p.strip_prefix("file://").unwrap_or(p));
                            if p.is_dir() {
                                n += upload_tree(&client, &d, &i, &p).await?;
                            } else {
                                api::drive::upload(&client, &d, &i, &p).await?;
                                n += 1;
                            }
                        }
                        json!({ "uploaded": n })
                    }
                    "folders" => {
                        let (d, i) = (s("drive_id"), s("item_id"));
                        let (here, items, rows) = tokio::join!(
                            async {
                                if i.is_empty() {
                                    api::drive::root(&client, &d).await
                                } else {
                                    api::drive::item(&client, &d, &i).await
                                }
                            },
                            api::drive::children(&client, &d, &i),
                            api::list_rows::for_folder(&client, &d, &i)
                        );
                        // Dates, sharing and Activity as Teams' lists show
                        // them (SharePoint's rows; Graph's times otherwise).
                        let rows = rows.unwrap_or_else(|e| {
                            tracing::warn!("picker rows: {e:#}");
                            Default::default()
                        });
                        let now = chrono::Local::now();
                        let items: Vec<serde_json::Value> = items?
                            .iter()
                            .map(|it| api::list_rows::decorate(it, rows.get(&it.sp_item.to_ascii_lowercase()), now))
                            .collect();
                        json!({ "drive_id": d, "item_id": i, "here": here?, "items": items })
                    }
                    other => anyhow::bail!("unknown drive action {other}"),
                })
            }
            .await;
            let (value, error) = match result {
                Ok(v) => (v.to_string(), String::new()),
                Err(e) => {
                    tracing::warn!("drive {op}: {}", short_error(&e));
                    (String::new(), short_error(&e))
                }
            };
            let _ = qt.queue(move |mut this| this.as_mut().drive_action_done(QString::from(op.as_str()), QString::from(value.as_str()), QString::from(error.as_str())));
        });
    }

    pub fn update_event(
        mut self: Pin<&mut Self>,
        id: &QString,
        subject: &QString,
        start_utc: &QString,
        end_utc: &QString,
    ) {
        let (id, subject, start, end) = (
            id.to_string(),
            subject.to_string(),
            start_utc.to_string(),
            end_utc.to_string(),
        );
        self.as_mut().set_status_text(QString::from(tr("Saving…")));
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let result = async {
                let client = TeamsClient::new().await?;
                api::calendar::update_event(&client, &id, &subject, &start, &end).await
            }
            .await;
            let _ = qt.queue(move |mut this| match result {
                Ok(()) => {
                    this.as_mut().set_status_text(QString::default());
                    this.as_mut().refresh_calendar();
                }
                Err(e) => this
                    .as_mut()
                    .set_status_text(QString::from(short_error(&e).as_str())),
            });
        });
    }

    pub fn delete_event(mut self: Pin<&mut Self>, id: &QString) {
        let id = id.to_string();
        self.as_mut().set_status_text(QString::from(tr("Deleting…")));
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let result = async {
                let client = TeamsClient::new().await?;
                api::calendar::delete_event(&client, &id).await
            }
            .await;
            let _ = qt.queue(move |mut this| match result {
                Ok(()) => {
                    this.as_mut().set_status_text(QString::default());
                    this.as_mut().refresh_calendar();
                }
                Err(e) => this
                    .as_mut()
                    .set_status_text(QString::from(short_error(&e).as_str())),
            });
        });
    }

    pub fn calendar_action(mut self: Pin<&mut Self>, op: &QString, args_json: &QString) {
        let op = op.to_string();
        let args: serde_json::Value = serde_json::from_str(&args_json.to_string()).unwrap_or(json!({}));
        let me = api::calendar::Me {
            name: self.rust().user_name.to_string(),
            mail: self.rust().user_mail.to_string(),
            mri: self.rust().my_mri.clone().unwrap_or_default(),
        };
        let busy = match op.as_str() {
            "respond" => tr("Sending your response…"),
            "schedule" => tr("Scheduling..."),
            "update" => tr("Sending update…"),
            "cancel" => tr("Cancelling…"),
            "propose" => tr("Sending your proposal…"),
            _ => String::new(),
        };
        if !busy.is_empty() {
            self.as_mut().set_status_text(QString::from(busy.as_str()));
        }
        let qt = self.qt_thread();
        let op2 = op.clone();
        runtime().spawn(async move {
            let s = |k: &str| args[k].as_str().unwrap_or_default().to_string();
            let result: anyhow::Result<serde_json::Value> = async {
                let client = TeamsClient::new().await?;
                match op.as_str() {
                    "detail" => api::calendar::event_detail(&client, &s("id")).await,
                    // Teams' calendar settings: Time scale, the day count,
                    // the Filter menu, Saved views, categories.
                    "prefs" => api::calendar::calendar_prefs(&client).await,
                    // Your other calendars (the pane's My calendars and
                    // Groups) and their events, for Split view.
                    "calendars" => Ok(json!({ "calendars": api::calendar::calendars(&client).await? })),
                    // The tile's menu: Charm, Show as, Categorize, Private.
                    "charm" => {
                        api::calendar::set_charm(&s("id"), args["charm"].as_i64().unwrap_or(0)).await?;
                        Ok(json!({}))
                    }
                    "patchEvent" => {
                        api::calendar::patch_event(&client, &s("id"), &args["patch"]).await?;
                        Ok(json!({}))
                    }
                    "calendarEvents" => {
                        let mut all = Vec::new();
                        for c in args["calendars"].as_array().into_iter().flatten().filter_map(|c| c.as_str()) {
                            match api::calendar::calendar_view_of(&client, c, &s("start"), &s("end")).await {
                                Ok(mut e) => all.append(&mut e),
                                Err(e) => tracing::warn!("calendar view: {}", short_error(&e)),
                            }
                        }
                        Ok(json!({ "events": all, "start": s("start") }))
                    }
                    "setFilters" => {
                        api::calendar::set_calendar_filters(&args["filters"]).await?;
                        Ok(json!({}))
                    }
                    "setSurface" => {
                        api::calendar::set_surface_options(&args).await?;
                        Ok(json!({}))
                    }
                    "saveView" => Ok(json!({ "view": api::calendar::save_calendar_view(&args["view"]).await? })),
                    "deleteView" => {
                        api::calendar::delete_calendar_view(&s("id")).await?;
                        Ok(json!({ "id": s("id") }))
                    }
                    // Tentative / Decline and propose new time.
                    "propose" => {
                        let target: api::calendar::RsvpTarget = serde_json::from_value(args["event"].clone()).unwrap_or_default();
                        api::calendar::propose_new_time(&client, &target, &s("response"), &s("start"), &s("end"), args["send"].as_bool().unwrap_or(true), &s("note")).await?;
                        Ok(json!({}))
                    }
                    "meetNow" => Ok(json!({ "joinUrl": api::calendar::meet_now(&client, &s("subject")).await?, "subject": s("subject") })),
                    // Cast's meetings step: your Teams meetings from an hour
                    // ago to an hour ahead (Teams' cast wizard).
                    "castMeetings" => {
                        let now = chrono::Utc::now();
                        let from = (now - chrono::Duration::minutes(60)).format("%Y-%m-%dT%H:%M:%SZ").to_string();
                        let to = (now + chrono::Duration::minutes(60)).format("%Y-%m-%dT%H:%M:%SZ").to_string();
                        let events = api::calendar::calendar_view(&client, &from, &to).await?;
                        let list: Vec<serde_json::Value> = api::calendar::cast_meetings(&events, now)
                            .into_iter()
                            .map(|e| json!({ "subject": e.subject, "start": e.start_utc, "end": e.end_utc, "allDay": e.is_all_day, "joinUrl": e.join_url }))
                            .collect();
                        Ok(json!({ "meetings": list }))
                    }
                    // Cast's "Just cast": an instant meeting (Teams'
                    // createAndGetInstantMeetingEventJoinInfo, a Meet now).
                    "castMeetNow" => Ok(json!({ "joinUrl": api::calendar::meet_now(&client, &s("subject")).await?, "subject": s("subject") })),
                    // As Teams: the calling service finds the meeting from
                    // its ID and passcode (meetingData); then its join link.
                    "joinById" => {
                        let (link, subject) = teams_cli::calling::outgoing::resolve_meeting_id(&s("meetingId"), &s("passcode"))
                            .await
                            .map_err(|e| {
                                tracing::warn!("join with an ID: {e:#}");
                                anyhow::anyhow!("We couldn't find a meeting with that ID and passcode.")
                            })?;
                        let enc = |t: &str| t.replace(':', "%3a").replace('@', "%40");
                        let ctx = match (&link.tenant_id, &link.organizer_id) {
                            (Some(t), Some(o)) => format!("?context=%7b%22Tid%22%3a%22{t}%22%2c%22Oid%22%3a%22{o}%22%7d"),
                            _ => String::new(),
                        };
                        Ok(json!({ "joinUrl": format!("https://teams.microsoft.com/l/meetup-join/{}/0{ctx}", enc(&link.thread_id)), "subject": if subject.is_empty() { "Meeting".to_string() } else { subject } }))
                    }
                    "respond" => {
                        // {event: {id, ical_uid, event_type, start_utc}, series}: a
                        // series answer is about its series (id, iCalUId, start).
                        let mut target: api::calendar::RsvpTarget = serde_json::from_value(args["event"].clone()).unwrap_or_default();
                        if target.id.is_empty() {
                            target.id = s("id");
                        }
                        if args["series"].as_bool() == Some(true) {
                            if let Some(master) = args["event"]["series_master_id"].as_str().filter(|m| !m.is_empty()) {
                                target.id = master.to_string();
                                target.event_type = "seriesMaster".into();
                                if let Ok(r) = client.graph_get(&format!("/me/events/{master}?$select=iCalUId,start")).await {
                                    let v: serde_json::Value = r.json().await.unwrap_or_default();
                                    target.ical_uid = v["iCalUId"].as_str().unwrap_or_default().to_string();
                                    if let Some(t) = v.pointer("/start/dateTime").and_then(|t| t.as_str()) {
                                        target.start_utc = format!("{}Z", t.split('.').next().unwrap_or(t));
                                    }
                                }
                            }
                        }
                        api::calendar::respond(&client, &target, &s("response"), args["send"].as_bool().unwrap_or(true), &s("note")).await?;
                        Ok(json!({}))
                    }
                    "schedule" => {
                        let form: api::calendar::MeetingForm = serde_json::from_value(args["form"].clone())?;
                        api::calendar::schedule(&client, &form, &me).await
                    }
                    "update" => {
                        let form: api::calendar::MeetingForm = serde_json::from_value(args["form"].clone())?;
                        api::calendar::update_meeting(&client, &s("id"), &form, &me, &s("joinUrl"), &s("eventType")).await?;
                        Ok(json!({}))
                    }
                    "cancel" => {
                        api::calendar::cancel_meeting(&client, &args["event"], &s("teamId"), &s("note")).await?;
                        Ok(json!({}))
                    }
                    "availability" => {
                        let people: Vec<(String, String)> = args["people"]
                            .as_array()
                            .into_iter()
                            .flatten()
                            .filter_map(|p| Some((p[0].as_str()?.to_string(), p[1].as_str().unwrap_or_default().to_string())))
                            .collect();
                        let (map, tz) = api::calendar::availability(&client, &me, &people, &s("start"), &s("end")).await?;
                        Ok(json!({ "freeBusy": map, "timeZone": tz }))
                    }
                    other => anyhow::bail!("Unknown calendar action {other}"),
                }
            }
            .await;
            let _ = qt.queue(move |mut this| {
                let (text, error) = match result {
                    Ok(v) => (v.to_string(), String::new()),
                    Err(e) => {
                        tracing::warn!(op = %op2, "calendar action failed: {}", short_error(&e));
                        (String::new(), short_error(&e))
                    }
                };
                if ["respond", "schedule", "update", "cancel", "propose", "charm", "patchEvent"].contains(&op2.as_str()) {
                    this.as_mut().set_status_text(QString::from(error.as_str()));
                    if error.is_empty() {
                        this.as_mut().refresh_calendar();
                    }
                }
                tracing::info!(op = %op2, ok = error.is_empty(), "calendar action");
                this.as_mut().calendar_action_done(QString::from(op2.as_str()), QString::from(text.as_str()), QString::from(error.as_str()));
            });
        });
    }

    pub fn create_event(
        mut self: Pin<&mut Self>,
        subject: &QString,
        start_utc: &QString,
        end_utc: &QString,
        attendees: &QString,
        teams_meeting: bool,
    ) {
        let (subject, start, end) = (
            subject.to_string(),
            start_utc.to_string(),
            end_utc.to_string(),
        );
        let attendees: Vec<String> = attendees
            .to_string()
            .split([',', ';'])
            .map(|a| a.trim().to_string())
            .filter(|a| !a.is_empty())
            .collect();
        self.as_mut().set_status_text(QString::from(tr("Scheduling...")));
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let result = async {
                let client = TeamsClient::new().await?;
                api::calendar::create_event(
                    &client,
                    &subject,
                    &start,
                    &end,
                    &attendees,
                    teams_meeting,
                )
                .await
            }
            .await;
            let _ = qt.queue(move |mut this| match result {
                Ok(ev) => {
                    this.as_mut().set_status_text(QString::from(
                        tr("Scheduled %1").replace("%1", &ev.subject).as_str(),
                    ));
                    this.as_mut().refresh_calendar();
                }
                Err(e) => this
                    .as_mut()
                    .set_status_text(QString::from(short_error(&e).as_str())),
            });
        });
    }

    pub fn reload_teams(self: Pin<&mut Self>) {
        self.load_teams();
    }

    pub fn mark_all_read(mut self: Pin<&mut Self>, app_type: &QString) {
        let app_type = app_type.to_string();
        // Channels: the teams list's unread flags, and channel threads in
        // the unread set.
        let mut teams: serde_json::Value = serde_json::from_str(&self.rust().teams_json.to_string()).unwrap_or_default();
        let channel_ids: HashSet<String> = teams
            .as_array()
            .into_iter()
            .flatten()
            .flat_map(|t| t["channels"].as_array().into_iter().flatten())
            .filter_map(|c| c["id"].as_str().map(String::from))
            .collect();
        let mut unread: Vec<String> = self.rust().unread.iter().cloned().collect();
        for t in teams.as_array().into_iter().flatten() {
            for c in t["channels"].as_array().into_iter().flatten() {
                if c["unread"] == json!(true)
                    && let Some(id) = c["id"].as_str()
                    && !unread.iter().any(|u| u == id)
                {
                    unread.push(id.to_string());
                }
            }
        }
        let ids = mark_all_targets(&app_type, &unread, &channel_ids);
        if ids.is_empty() {
            return;
        }
        let mut teams_changed = false;
        for t in teams.as_array_mut().into_iter().flatten() {
            for c in t["channels"].as_array_mut().into_iter().flatten() {
                if c["unread"] == json!(true) && c["id"].as_str().is_some_and(|id| ids.iter().any(|i| i == id)) {
                    c["unread"] = json!(false);
                    teams_changed = true;
                }
            }
        }
        if teams_changed {
            self.as_mut().set_teams_json(QString::from(teams.to_string().as_str()));
        }
        for id in &ids {
            self.as_mut().rust_mut().unread.remove(id);
        }
        self.as_mut().publish_chats();
        tracing::info!(%app_type, count = ids.len(), "mark all as read");
        runtime().spawn(async move {
            let Ok(client) = TeamsClient::new().await else {
                return;
            };
            for id in ids {
                if let Err(e) = api::messages::mark_chat_read_to_latest(&client, &id).await {
                    tracing::debug!("mark read failed: {}", short_error(&e));
                }
            }
            tracing::info!("marked all read");
        });
    }

    pub fn set_my_status(self: Pin<&mut Self>, status: &QString) {
        // Teams' default duration is Today (Reset has none).
        self.set_my_status_until(status, &QString::from("Today"), &QString::default());
    }

    /// Set your status as Teams does (forceavailability with
    /// desiredExpirationTime from the Duration choice; Custom takes an ISO
    /// local time), dropping repeats as Teams' manager does.
    pub fn set_my_status_until(
        mut self: Pin<&mut Self>,
        status: &QString,
        duration: &QString,
        custom: &QString,
    ) {
        use std::sync::Mutex;
        // (availability, duration) of the last request, when it was sent, and
        // whether it is still pending.
        static LAST: Mutex<Option<(String, String, std::time::Instant, bool)>> = Mutex::new(None);
        let status = status.to_string();
        let duration = duration.to_string();
        let custom = custom.to_string();
        // A custom end is part of the choice (Pause notifications' 10
        // minutes twice is two different ends).
        let choice = format!("{duration}|{custom}");
        {
            let last = LAST.lock().unwrap();
            if let Some((a, d, at, pending)) = last.as_ref() {
                let same = *a == status && *d == choice;
                // Identical while in flight, any request within 10 s of a
                // pending one, or equal to the current one within 300 s.
                if (*pending && (same || at.elapsed().as_secs() < 10))
                    || (same && at.elapsed().as_secs() < 300)
                {
                    return;
                }
            }
        }
        *LAST.lock().unwrap() = Some((
            status.clone(),
            choice,
            std::time::Instant::now(),
            true,
        ));
        let forced = (status != "Reset").then(|| status.clone());
        if let (Some(f), Some(me)) = (forced.clone(), self.rust().my_mri.clone()) {
            self.as_mut().rust_mut().presence.insert(me, f);
            self.as_mut().publish_chats();
        }
        let until = if duration == "Custom" {
            chrono::DateTime::parse_from_rfc3339(&custom)
                .ok()
                .map(|t| t.with_timezone(&chrono::Local))
        } else {
            teams_cli::api::presence::expiry_for(&duration, chrono::Local::now())
        };
        let until = forced.as_ref().and(until);
        let until_iso = until
            .map(|t| t.with_timezone(&chrono::Utc).to_rfc3339_opts(chrono::SecondsFormat::Millis, true))
            .unwrap_or_default();
        self.as_mut().set_my_status_ends(QString::from(until_iso.as_str()));
        let me = self.rust().my_mri.clone();
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let http = reqwest::Client::new();
            let sent = teams_cli::api::presence::force_availability_until(&http, forced.as_deref(), until).await;
            if let Err(e) = &sent {
                tracing::warn!("set status failed: {}", short_error(e));
            }
            if let Some(l) = LAST.lock().unwrap().as_mut() {
                l.3 = false;
            }
            // Reset: your status is what your activity says again, so
            // read it back now rather than at the next refresh.
            if sent.is_ok()
                && forced.is_none()
                && let Some(me) = me
                && let Ok(list) = teams_cli::api::presence::get_presences(&http, std::slice::from_ref(&me)).await
                && let Some(p) = list.into_iter().next()
            {
                let _ = qt.queue(move |mut this| {
                    this.as_mut().set_my_status_ends(QString::from(p.forced_until.as_str()));
                    this.as_mut().rust_mut().presence.insert(p.mri, p.availability);
                    this.as_mut().publish_chats();
                });
            }
        });
    }

    /// Set your status message (Teams' publishnote): `message`, shown when
    /// people message you if `pinned`, cleared after `clear_after` (Never,
    /// Today, OneHour, FourHours, ThisWeek, or Custom with `custom`).
    pub fn set_status_note(
        self: Pin<&mut Self>,
        message: &QString,
        pinned: bool,
        clear_after: &QString,
        custom: &QString,
    ) {
        let (message, choice, custom) = (
            message.to_string(),
            clear_after.to_string(),
            custom.to_string(),
        );
        let until = if choice == "Custom" {
            chrono::DateTime::parse_from_rfc3339(&custom)
                .ok()
                .map(|t| t.with_timezone(&chrono::Local))
        } else {
            teams_cli::api::presence::expiry_for(&choice, chrono::Local::now())
        };
        let qt = self.qt_thread();
        runtime().spawn(async move {
            let http = reqwest::Client::new();
            let result =
                teams_cli::api::presence::publish_note(&http, &message, pinned, until).await;
            let _ = qt.queue(move |mut this| {
                // Yours as the presence service will now say (Never is the
                // year 9999).
                if result.is_ok() {
                    let cleared = message.trim().is_empty();
                    let note = json!({
                        "text": if cleared { String::new() } else { teams_cli::api::presence::note_plain(&message) },
                        "html": if cleared { String::new() } else { teams_cli::api::messages::sanitize_html_marking(&teams_cli::api::presence::note_html_any(&message), &[]) },
                        "pinned": pinned && !cleared,
                        "expiry": if cleared { String::new() } else { until.map(|t| t.with_timezone(&chrono::Utc).to_rfc3339_opts(chrono::SecondsFormat::Millis, true)).unwrap_or_else(|| "9999-12-31T23:59:59.999Z".into()) },
                    })
                    .to_string();
                    this.as_mut().set_my_note_json(QString::from(note.as_str()));
                }
                let text = match &result {
                    Ok(()) => json!({
                        "ok": true,
                        "message": teams_cli::api::presence::note_plain(&message),
                        "html": if message.trim().is_empty() { String::new() } else { teams_cli::api::messages::sanitize_html_marking(&teams_cli::api::presence::note_html_any(&message), &[]) },
                        "pinned": pinned,
                    }),
                    Err(e) => json!({ "ok": false, "error": short_error(e) }),
                };
                this.as_mut()
                    .set_status_note_result(QString::from(text.to_string().as_str()));
            });
        });
    }

